(function (root) {
  'use strict';
  // Original worked examples and retrieval checks supplement the course summaries.
  // These are focused review lessons, not an exhaustive College Board curriculum.
  function topic(name, teach, trap) { return { name: name, teach: teach, trap: trap }; }
  function lesson(topics, prompt, steps, answer, checkPrompt, checkAnswer) {
    return { topics: topics, example: { prompt: prompt, steps: steps, answer: answer }, check: { prompt: checkPrompt, answer: checkAnswer } };
  }
  const t = topic, l = lesson;
  const lessons = {
    apcsp: [
      l([t('Input, output, and behavior', 'Input supplies data; output communicates a result. Describe what a user does and how the program responds before discussing implementation.', 'A button is an input mechanism, not the entire program purpose.'), t('Testing and error types', 'Syntax errors break language rules; runtime errors occur during execution; logic errors produce unintended results. Test typical, boundary, and unexpected inputs.', 'One successful test does not prove that all inputs work.')], 'A ticket app discounts ages below 12. Which ages test the boundary?', ['Choose values immediately on both sides of the decision.', 'Compare the observed price against the stated rule.'], 'Ages 11 and 12: 11 receives the discount; 12 does not.', 'A program runs but doubles a total instead of adding a fee. What kind of error is this?', 'A logic error: execution succeeds but the implemented behavior is wrong.'),
      l([t('Binary representation', 'With n bits there are 2ⁿ patterns. Unsigned values range from 0 through 2ⁿ−1; adding bits doubles the number of patterns.', 'The largest unsigned value is not 2ⁿ.'), t('Data cleaning and metadata', 'Metadata describes data, such as units or collection time. Clean inconsistent formats before combining records, and inspect missing values before drawing conclusions.', 'A larger dataset can still be biased or measured inconsistently.')], 'How many distinct unsigned values fit in 5 bits?', ['Each bit has two possibilities.', 'Multiply five factors of 2; the first value is zero.'], '32 distinct values, from 0 to 31.', 'Why should temperatures labeled °C and °F not be averaged directly?', 'They use different scales; convert to a common unit before analysis.'),
      l([t('Tracing selection and iteration', 'Track each variable after each assignment. A condition is checked at the point the algorithm specifies; a loop may execute zero times.', 'Do not update every variable simultaneously unless the algorithm says so.'), t('Searching and simulations', 'Linear search can inspect every item; binary search repeatedly halves a sorted search interval. A simulation approximates a system using explicit assumptions.', 'Binary search requires ordered data; a simulation is not reality.')], 'Set total to 0. For each value in [2,5,8], add it only if it is greater than 4. What is total?', ['2 fails the condition, so total stays 0.', '5 makes total 5; 8 makes total 13.'], '13.', 'Can ordinary binary search reliably find an item in an unsorted list?', 'No. Its decision about which half to discard relies on sorted order.'),
      l([t('Packets and addressing', 'Messages are divided into packets that can follow different routes. IP addresses identify destinations; DNS translates domain names into IP addresses.', 'The internet and the World Wide Web are not synonyms.'), t('Parallel speedup limits', 'Independent tasks can run concurrently, but sequential work and coordination limit speedup. Compare total completion time, not just processor count.', 'Twice as many processors does not guarantee half the time.')], 'Independent tasks take 4 and 6 seconds. Ignore overhead. Compare sequential and parallel times.', ['Sequential execution adds the durations.', 'Parallel execution finishes when the slower task finishes.'], 'Sequential: 10 s. Parallel: 6 s. Speedup: 10/6 ≈ 1.67.', 'Does DNS guarantee a website is trustworthy?', 'No. Name resolution maps a domain to an address; it does not validate the site’s claims.'),
      l([t('Bias in computing', 'Biased sampling, labels, design choices, or unequal deployment can produce unequal outcomes. Evaluate who is represented and who bears the errors.', 'Removing a sensitive attribute does not remove all correlated proxies.'), t('Authentication and encryption', 'Authentication checks identity; encryption protects readable data using keys. Multifactor authentication combines different factor types, such as a password and a device.', 'Two passwords are not two different authentication factors.')], 'A scholarship model is trained only on previous recipients from wealthy districts. What risk follows?', ['Identify the missing population in the training sample.', 'Connect that omission to predictions about new applicants.'], 'The model may systematically undervalue qualified applicants from other districts; audit representation and errors.', 'Is a password plus an authenticator app stronger than a password alone?', 'Generally yes: access requires both knowledge of the password and possession of the second factor.')
    ],
    apcsa: [
      l([t('Primitive arithmetic and casting', 'Java integer division truncates toward zero. Convert an operand to double before division to preserve a fractional result.', 'Casting the already-truncated result cannot restore lost information.'), t('String operations and equality', 'Strings are immutable. substring uses an inclusive start and exclusive end; equals compares String contents while == compares references.', 'Do not compare independently constructed String contents with ==.')], 'Evaluate 7 / 2 and (double) 7 / 2.', ['Both operands in the first expression are integers.', 'Casting 7 changes the second division to floating point.'], '3 and 3.5.', 'What does "Scholark".substring(0,3) return?', '"Sch": indices 0, 1, and 2.'),
      l([t('Boolean transformations', 'De Morgan’s laws give !(A && B) = !A || !B and !(A || B) = !A && !B. Negate comparisons carefully.', 'The negation of x < 5 is x >= 5, not x > 5.'), t('Loop boundaries and tracing', 'A for loop initializes once, checks before each iteration, and updates after the body. Nested-loop work depends on both bounds.', 'An inclusive upper bound usually adds one iteration.')], 'How often does for(int i=1;i<=3;i++) run its body?', ['Check i = 1, 2, and 3: each satisfies the condition.', 'After the third update, i = 4 fails the condition.'], '3 times.', 'Negate x >= 0 && x < 10.', 'x < 0 || x >= 10.'),
      l([t('Instance versus static members', 'Each object has its own instance fields. A static field belongs to the class and is shared across its instances.', 'Changing one instance field does not change every other object.'), t('Parameters and this', 'Parameters receive copies of argument values. this identifies the current object and can distinguish an instance field from a same-named parameter.', 'Assigning a parameter alone does not update the instance field.')], 'Why does a constructor use this.name = name?', ['The parameter named name hides the field name inside this scope.', 'this.name explicitly refers to the new object’s field.'], 'It copies the supplied parameter value into the instance field.', 'If two new Counter objects each have an instance count initialized to 0, does incrementing one change the other?', 'No. Their instance fields are separate.'),
      l([t('Arrays and bounds', 'Array indices range from 0 to length−1. Use array.length, String.length(), and ArrayList.size() with their correct syntax.', 'An index equal to the length is outside the array.'), t('Search and accumulation', 'Initialize a sum before traversal. Initialize a maximum from an actual element when values may all be negative; handle empty collections explicitly.', 'A maximum initialized to 0 fails for an all-negative list.')], 'Find the maximum of [-8,-3,-11].', ['Initialize max to the first element, −8.', 'Replace it with −3; −11 is smaller.'], '−3.', 'Why can removing items during an enhanced-for traversal of an ArrayList fail?', 'Structural modification conflicts with the traversal; use an appropriate index-based strategy instead.')
    ],
    apcalcab: [
      l([t('One-sided limits', 'A two-sided limit exists only when left- and right-hand limits agree. A vertical asymptote describes unbounded nearby behavior.', 'A function value cannot repair unequal one-sided limits.'), t('Intermediate value theorem', 'A continuous function on [a,b] takes every value between f(a) and f(b). State continuity before using the theorem.', 'The theorem guarantees existence, not uniqueness.')], 'Find lim as x→2 of (x²−4)/(x−2).', ['Factor the numerator as (x−2)(x+2).', 'For x≠2 the quotient is x+2; evaluate its nearby behavior.'], '4, even though the original expression is undefined at 2.', 'Left limit is 3 and right limit is 5. Does the two-sided limit exist?', 'No; the one-sided limits disagree.'),
      l([t('Product and quotient rules', 'Differentiate fg as f′g+fg′ and f/g as (f′g−fg′)/g² where g≠0. Preserve the numerator order.', 'The derivative of a product is not simply f′g′.'), t('Derivative definition', 'The limit [f(a+h)−f(a)]/h as h→0 connects secant slopes to the tangent slope.', 'Simplify before substituting h=0 into a 0/0 expression.')], 'Differentiate x² sin x.', ['Identify a product of x² and sin x.', 'Differentiate each factor in its own product-rule term.'], '2x sin x + x² cos x.', 'What are the units of dV/dt if V is liters and t is minutes?', 'Liters per minute.'),
      l([t('Inverse derivatives', 'If f is invertible and f′(a)≠0, then (f⁻¹)′(f(a)) = 1/f′(a). Match the input and output points.', 'Evaluate f′ at the original input, not automatically at f(a).'), t('Higher derivatives', 'Differentiate the first derivative again to obtain a second derivative. Implicit expressions may require substituting the earlier y′ result.', 'A second derivative describes change in slope, not the original slope.')], 'For x²+y²=25, find dy/dx at (3,4).', ['Differentiate: 2x + 2y y′ = 0.', 'Solve y′ = −x/y and substitute the point.'], '−3/4.', 'Differentiate (3x+1)⁴.', '12(3x+1)³ by the chain rule.'),
      l([t('Position, velocity, and speed', 'Velocity is position’s derivative; acceleration is velocity’s derivative. Speed is |v| and increases when v and a have the same sign.', 'Negative velocity alone does not mean slowing down.'), t('Rates with context', 'Translate a derivative into a statement containing the quantity, time, magnitude, and units. Distinguish an amount from its rate of change.', 'A negative second derivative need not imply a negative first derivative.')], 'At t=2, velocity is −3 m/s and acceleration is −2 m/s². Is speed increasing?', ['Velocity and acceleration have the same sign.', 'The velocity becomes more negative, increasing its magnitude.'], 'Yes; the object moves in the negative direction and speeds up.', 'A tank has V′(5)=−4 L/min. Interpret it.', 'At 5 minutes, the amount of water is decreasing at 4 liters per minute.'),
      l([t('First derivative sign tests', 'A derivative changing from positive to negative gives a local maximum; negative to positive gives a local minimum.', 'A zero derivative alone does not establish an extremum.'), t('Concavity and inflection', 'Where f′ increases, f is concave up; where f′ decreases, f is concave down. An inflection requires a change in concavity.', 'f″=0 supplies a candidate, not proof of inflection.')], 'For f(x)=x³−3x, classify the critical points.', ['f′=3x²−3, so x=−1 and x=1.', 'The derivative signs are +, −, + across those points.'], 'Local maximum at x=−1; local minimum at x=1.', 'Does x³ have a local maximum or minimum at 0?', 'Neither: its derivative is positive on both sides of 0.'),
      l([t('Riemann sums and trapezoids', 'Approximate an integral using widths times heights. On unequal subintervals, use each interval’s own width.', 'Counting data points does not give the number of subintervals.'), t('Substitution and bounds', 'Choose u so du matches the remaining factor. For definite integrals, either change the bounds to u or return to x before evaluation.', 'Do not combine u-antiderivatives with unchanged x-bounds.')], 'Evaluate ∫ from 0 to 1 of 2x(x²+1) dx.', ['Set u=x²+1 and du=2x dx.', 'The new bounds are 1 and 2; integrate u.'], '[u²/2] from 1 to 2 = 3/2.', 'If F(x)=∫ from 0 to x² of cos t dt, find F′(x).', '2x cos(x²), including the derivative of the upper bound.'),
      l([t('Initial conditions', 'A differential equation describes a family of solutions. An initial condition selects a member; check the solution in both the equation and condition.', 'An antiderivative without its constant may miss the intended solution.'), t('Exponential growth and decay', 'For y′=ky, y=Ce^(kt). Positive k produces growth for positive y; negative k produces decay.', 'Constant proportional growth is not constant additive growth.')], 'Solve y′=2y with y(0)=3.', ['The general solution is Ce^(2t).', 'At t=0, C=3.'], 'y=3e^(2t).', 'If y′=y−4, what constant solution is possible?', 'y=4, because its derivative and the right-hand side are both zero.'),
      l([t('Area between curves', 'Integrate top minus bottom over an x-interval, splitting where the curves switch order. Geometric area is nonnegative.', 'An unsplit signed integral can cancel separate regions.'), t('Disk and washer volumes', 'A washer’s area is π(R²−r²), using distances from the rotation axis. Radii may require shifting by the axis value.', 'π(R−r)² is not the washer area.')], 'Find the area between y=x and y=x² on [0,1].', ['x is above x² on this interval.', 'Integrate x−x² from 0 to 1.'], '1/2−1/3 = 1/6 square units.', 'What is the volume when the region below y=x on [0,1] rotates around the x-axis?', 'π∫₀¹x² dx = π/3 cubic units.')
    ],
    apcalcbc: [
      l([t('Derivative tests and theorem conditions', 'Use derivative signs to justify extrema and concavity. Verify continuity and differentiability before invoking the mean value theorem.', 'A stationary point is not automatically a maximum or minimum.'), t('Logarithmic and exponential derivatives', 'The derivatives of ln|u| and eᵘ are u′/u and eᵘu′. Chain factors matter in limit and differential-equation work.', 'L’Hospital’s rule applies to qualifying indeterminate ratios, not every quotient.')], 'Evaluate lim as x→0 of (e^(2x)−1)/x.', ['Direct substitution produces 0/0.', 'Differentiate numerator and denominator under L’Hospital’s rule.'], 'lim 2e^(2x) = 2.', 'Does lim as x→0 of (x+1)/(x+2) require L’Hospital’s rule?', 'No. Direct substitution gives 1/2; the form is not indeterminate.'),
      l([t('Partial fractions', 'Decompose a rational function with factorable denominator into simpler fractions, then integrate each term. Perform polynomial division first if needed.', 'Match coefficients after multiplying through by the common denominator.'), t('Logistic differential equations', 'For y′=ky(1−y/L), L is a positive carrying capacity. Growth is fastest at y=L/2 for k>0.', 'The fastest growth occurs before reaching carrying capacity.')], 'Evaluate ∫ from 1 to ∞ of 1/x² dx.', ['Replace infinity with b and integrate: [−1/x] from 1 to b.', 'Take the limit of 1−1/b as b→∞.'], 'The improper integral converges to 1.', 'Does ∫ from 1 to ∞ of 1/x dx converge?', 'No. ln b grows without bound.'),
      l([t('Parametric acceleration and distance', 'Differentiate position components to obtain velocity. Speed is √((x′)²+(y′)²); integrating speed gives distance traveled.', 'Integrating a single component gives displacement, not total distance.'), t('Polar slopes', 'Write x=r cos θ and y=r sin θ before differentiating. Then dy/dx=(dy/dθ)/(dx/dθ) where the denominator is nonzero.', 'A negative r is allowed and changes the plotted direction.')], 'A particle has x=3t and y=4t for 0≤t≤2. Find distance traveled.', ['Velocity components are 3 and 4.', 'Speed is √(9+16)=5; integrate it for 2 time units.'], '10 distance units.', 'For x=t² and y=t³, what is dy/dx at t=1?', '(3t²)/(2t) at 1 = 3/2.'),
      l([t('Power-series endpoints', 'The ratio test often finds the radius of convergence. Test each endpoint separately in the original series.', 'A radius alone does not specify whether endpoints are included.'), t('Geometric and alternating series', 'A geometric series converges when |r|<1. An alternating series converges when magnitudes decrease to zero; its next term bounds truncation error.', 'Terms approaching zero are necessary but not sufficient for general convergence.')], 'Find the sum of Σ from n=0 to ∞ of 3(1/2)ⁿ.', ['Recognize first term 3 and ratio 1/2.', 'Since |r|<1, use a/(1−r).'], 'The sum is 6 because 3/(1−1/2)=6.', 'Does Σ 1/n converge merely because 1/n approaches 0?', 'No. The harmonic series diverges.')
    ],
    apstats: [
      l([t('Distribution shape and summaries', 'Compare shape, center, spread, and unusual features in context. Median and IQR resist extreme values better than mean and standard deviation.', 'Always compare the distributions explicitly rather than describing each in isolation.'), t('Blocking and matched pairs', 'Blocking groups similar experimental units before random assignment within groups. Matched pairs compare closely related observations, often the same person twice.', 'Blocking is not the same as randomly sampling a population.'), t('Bias and scope of inference', 'Nonresponse and voluntary-response selection can bias estimates. Random sampling supports population generalization; random assignment supports causal inference.', 'A large biased sample does not become representative just by growing.')], 'Volunteers are randomly assigned to two study methods. What can the study justify?', ['Random assignment balances potential confounders in expectation.', 'Volunteers were not randomly selected from all students.'], 'A causal comparison for the experimental group, with limited grounds for generalizing to every student.', 'Why use a placebo and blinding?', 'To reduce effects of expectations and differential treatment apart from the intended explanatory variable.'),
      l([t('Normal-model probabilities', 'Standardize an observation using z=(x−μ)/σ and find the requested tail area under a justified normal model.', 'A z-score describes location; it is not itself a probability.'), t('Independence versus disjointness', 'Independent events satisfy P(A∩B)=P(A)P(B). Disjoint events cannot occur together; positive-probability disjoint events are not independent.', 'Mutually exclusive does not mean independent.'), t('Binomial models', 'A binomial count requires fixed trials, independent outcomes, two categories, and constant success probability. Its mean is np and standard deviation √(np(1−p)).', 'Sampling without replacement may require checking the population size.')], 'For 10 independent trials with success probability 0.3, find the expected count.', ['Identify n=10 and p=0.3.', 'Use E(X)=np.'], '3 successes; this is a long-run average, not a guaranteed outcome.', 'If P(A)=0.4 and P(B)=0.5 for independent events, what is P(A and B)?', '0.2.'),
      l([t('Conditions for proportion inference', 'For a one-proportion z test, check random sampling or assignment, independence, and sufficiently large expected success and failure counts under the null hypothesis.', 'Use the null proportion for the test standard error, not the observed proportion.'), t('Interpreting a confidence level', 'A 95% confidence procedure captures the fixed population parameter in about 95% of intervals over repeated random samples under the model conditions.', 'After an interval is calculated, do not assign a 95% probability to a fixed parameter being inside it.')], 'In 200 independent random observations, 120 are successes. Test against p=0.5 using a z statistic.', ['The observed proportion is 120/200=0.60; expected counts under the null are 100 and 100.', 'The null standard error is sqrt(0.5×0.5/200), about 0.03536.'], 'z=(0.60−0.50)/0.03536≈2.83; choose the appropriate one- or two-sided tail from the stated alternative.', 'Does a small p-value give the probability that the null hypothesis is true?', 'No. It measures how unusual the observed statistic or a more extreme one would be if the null model were true.'),
      l([t('One-sample t inference', 'When estimating a population mean with unknown population standard deviation, use s/sqrt(n) as estimated standard error and a t distribution with n−1 degrees of freedom when conditions hold.', 'Small samples with strong skew or outliers can invalidate a routine t analysis.'), t('Analyzing paired differences', 'For matched measurements, compute one difference per pair and perform inference on the mean difference. Independence concerns the different pairs, not the two measurements within a pair.', 'Treating paired observations as independent groups loses the design’s information.')], 'A random sample of 25 differences has mean 4 and standard deviation 10. Find the t statistic for a null mean difference of zero.', ['The estimated standard error is 10/sqrt(25)=2.', 'Divide the difference from the null value by its standard error.'], 't=4/2=2 with 24 degrees of freedom, subject to the distribution and independence conditions.', 'Does failing to reject a null hypothesis prove that there is no effect?', 'No. The data may be too imprecise to distinguish a meaningful effect from zero; report the interval and uncertainty.'),
      l([t('Least-squares interpretation', 'A regression slope estimates the change in predicted y per unit increase in x. The intercept is meaningful only when x=0 is relevant.', 'A fitted association does not establish a causal mechanism.'), t('Residual plots and r²', 'Patterned residuals suggest an inadequate linear model. r² is the fraction of variation in y explained by the fitted linear relationship.', 'r² is not the fraction of points lying on the line.')], 'The fitted line is ŷ=10+2x. At x=4, observed y=21. Find the residual.', ['Predicted y=10+2(4)=18.', 'Residual=observed−predicted.'], '3; the observation lies above the fitted line.', 'What does a curved residual pattern suggest?', 'The linear model misses systematic curvature; consider a different model or transformation.')
    ],
    apbio: [
      l([t('Macromolecule assembly', 'Dehydration reactions join subunits while releasing water; hydrolysis uses water to break covalent links. Structure determines the resulting molecule’s function.', 'Breaking a bond itself requires energy; consider the entire reaction.'), t('Nucleic acids and directionality', 'DNA and RNA consist of nucleotide chains with a sugar-phosphate backbone. Base sequence carries information; complementary pairing supports accurate copying.', 'A nucleotide and an amino acid are different kinds of monomers.')], 'An enzyme loses activity after a large pH change. Explain a likely mechanism.', ['pH changes the protonation and charge of some amino acid side chains.', 'Altered interactions can change the shape or chemistry of the active site.'], 'Substrate binding or catalysis can fail even if the amino acid sequence remains unchanged.', 'Why does water help stabilize temperature?', 'Hydrogen bonding gives water a high specific heat, so considerable energy is needed to change its temperature.'),
      l([t('Osmosis and tonicity', 'Water moves across a selectively permeable membrane toward lower water potential. In a simple comparison, higher nonpenetrating solute concentration draws water.', 'Water movement is not active transport.'), t('Compartmentalization', 'Membranes separate cellular processes and maintain gradients. Ribosomes synthesize proteins; rough ER and Golgi help process and route many exported proteins.', 'Plant cells have both a cell membrane and a cell wall; they are not the same structure.')], 'An animal cell is placed in a solution with higher nonpenetrating solute concentration. Predict the change.', ['The outside is hypertonic relative to the cell.', 'Net water movement is outward.'], 'The cell loses water and shrinks.', 'Which structure synthesizes a secreted protein before it passes through ER and Golgi?', 'A ribosome associated with rough ER.'),
      l([t('Respiration and electron carriers', 'Glycolysis begins glucose breakdown; NADH and FADH₂ transfer electrons to the respiratory electron transport chain. Oxygen is the final electron acceptor in aerobic respiration.', 'Oxygen is not directly consumed in glycolysis.'), t('Photosynthesis and carbon fixation', 'Light reactions produce ATP and NADPH. The Calvin cycle uses them to reduce carbon from CO₂ into carbohydrate precursors.', 'Most plant biomass carbon comes from CO₂, not from soil.')], 'A poison blocks electron transfer to oxygen. Why does ATP production fall?', ['Electron transport can no longer maintain proton pumping.', 'The proton gradient weakens, reducing ATP synthase activity.'], 'Oxidative phosphorylation decreases; substrate-level phosphorylation may still produce some ATP.', 'Does an enzyme change the overall free-energy difference of a reaction?', 'No. It lowers activation energy without changing ΔG or the equilibrium position.'),
      l([t('Feedback and homeostasis', 'Negative feedback counteracts a disturbance; positive feedback amplifies a process until an endpoint. Identify the variable and the response direction.', 'Positive does not mean beneficial; negative does not mean harmful.'), t('Mitosis and chromosome accounting', 'DNA replicates during S phase before mitosis. Sister chromatids separate during mitosis, preserving chromosome number in daughter nuclei.', 'DNA replication doubles DNA content, not the number of centromere-defined chromosomes immediately.')], 'Blood glucose rises and insulin promotes cellular uptake. Classify the feedback.', ['The disturbance is increased glucose.', 'The response lowers glucose toward the regulated range.'], 'Negative feedback.', 'Why can a mutation disabling a checkpoint increase cancer risk?', 'Cells with damage may continue dividing instead of pausing, repairing, or undergoing programmed death.'),
      l([t('Linkage and recombination', 'Nearby genes on one chromosome tend to be inherited together. Crossing over can separate alleles, with recombination frequency informing relative map distance.', 'Independent assortment does not apply identically to closely linked genes.'), t('Probability in genetic crosses', 'Combine gamete probabilities to predict offspring genotypes. Dominance describes heterozygote phenotype, not allele frequency or evolutionary superiority.', 'Dominant does not mean common or better.')], 'For Aa × Aa with complete dominance, predict the genotype ratio.', ['Each parent produces A and a gametes with equal probability.', 'Combine the four equally likely pairs.'], '1 AA : 2 Aa : 1 aa; phenotype ratio 3 dominant : 1 recessive.', 'Can two unaffected carriers of a recessive condition have an affected child?', 'Yes. Aa × Aa gives a 1/4 probability of aa per offspring.'),
      l([t('Transcription and translation', 'RNA polymerase makes RNA from a DNA template. Ribosomes read mRNA codons; tRNAs bring corresponding amino acids.', 'The template DNA sequence is complementary to the RNA, not identical to it.'), t('Gene regulation and cell identity', 'Cells with the same genome can express different genes through transcription factors and chromatin regulation. Environmental signals can alter expression.', 'Different cell functions do not usually require completely different genomes.')], 'A coding-region insertion adds one nucleotide. Why can many downstream amino acids change?', ['Codons are read in groups of three.', 'A one-base insertion shifts how downstream bases are grouped.'], 'A frameshift can alter downstream codons and introduce an early stop.', 'Does every base substitution change an amino acid?', 'No. The genetic code is redundant, so some substitutions are synonymous.'),
      l([t('Genetic drift and gene flow', 'Drift is random allele-frequency change, especially strong in small populations. Gene flow moves alleles between populations through migration and reproduction.', 'Not every allele-frequency change is adaptive.'), t('Speciation and reproductive isolation', 'Reduced gene flow allows populations to diverge. Prezygotic barriers prevent fertilization; postzygotic barriers reduce hybrid viability or fertility.', 'Geographic separation alone is not proof that speciation is complete.')], 'A storm randomly kills most members of a population. Why may allele frequencies change?', ['Survival in this scenario is not tied to the allele’s effect.', 'The survivors are a small, unrepresentative sample.'], 'A population bottleneck causes genetic drift.', 'If q²=0.09 under Hardy–Weinberg assumptions, what is the heterozygote frequency?', 'q=0.3, p=0.7, so 2pq=0.42.'),
      l([t('Community interactions', 'Competition reduces access to shared resources; predation transfers energy between organisms. Mutualism benefits both partners, while parasitism benefits one at the other’s cost.', 'A food web arrow usually follows energy from resource to consumer.'), t('Disturbance and succession', 'Disturbance changes community structure. Primary succession begins without developed soil; secondary succession begins where soil remains.', 'Succession need not follow one fixed path to an unchanging endpoint.')], 'Removing a predator increases herbivores, and plant biomass falls. Explain the pattern.', ['Predator loss releases herbivores from some predation pressure.', 'More herbivory removes plant biomass.'], 'A trophic cascade links predator loss to producers through herbivores.', 'At carrying capacity in a simple logistic model, what is net population growth?', 'Approximately zero because births and immigration balance deaths and emigration in the modeled population.')
    ],
    apchem: [
      l([t('Moles and composition', 'Convert mass to moles using molar mass; ratios of moles determine empirical formulas. Keep particle identity explicit when using Avogadro’s number.', 'Equal masses of different substances generally contain different numbers of particles.'), t('Electron configuration', 'Valence electrons govern many chemical properties. Ion formation changes electron count; cations are generally smaller than their neutral atoms.', 'Atomic number counts protons, not electrons in every ion.')], 'How many moles are in 18.0 g H₂O? Use 18.0 g/mol.', ['Identify molar mass as grams per mole.', 'Divide mass by molar mass.'], '1.00 mol H₂O.', 'Why does first ionization energy generally increase across a period?', 'Increasing effective nuclear attraction holds valence electrons more tightly, with subshell and pairing exceptions.'),
      l([t('Lewis structures and geometry', 'Count valence electrons, connect atoms, and allocate remaining electrons. VSEPR uses electron domains to predict shape, including the effects of lone pairs.', 'Electron-domain geometry and molecular geometry can differ.'), t('Bond polarity versus molecular polarity', 'Electronegativity differences create bond dipoles. Molecular shape determines whether those vectors cancel.', 'Polar bonds do not guarantee a polar molecule.')], 'Why is CO₂ nonpolar even though C=O bonds are polar?', ['CO₂ is linear with equivalent bonds on opposite sides.', 'The equal bond dipoles point in opposite directions.'], 'Their vector sum is zero.', 'What is the molecular shape of H₂O?', 'Bent: oxygen has two bonding domains and two lone pairs.'),
      l([t('Gas laws and particle motion', 'For ideal gases, PV=nRT. Temperature must be in kelvin; at equal temperature gases have equal average kinetic energy, not equal average speed.', 'Celsius cannot be substituted into absolute-temperature gas relationships.'), t('Solutions and concentration', 'Molarity is moles of solute per liter of solution. Dilution conserves solute moles when no reaction occurs: M₁V₁=M₂V₂.', 'Adding solvent changes concentration, not the number of solute moles.')], 'Dilute 25.0 mL of 2.00 M solution to 100.0 mL. Find the final concentration.', ['Apply conservation of solute: M₁V₁=M₂V₂.', 'Compute 2.00×25.0/100.0.'], '0.500 M.', 'Why does boiling water not require breaking its O–H covalent bonds?', 'Boiling separates molecules by overcoming intermolecular attractions; the water molecules remain chemically intact.'),
      l([t('Oxidation and reduction', 'Oxidation increases oxidation number; reduction decreases it. Electrons lost equal electrons gained in a balanced redox reaction.', 'The reducing agent is itself oxidized.'), t('Precipitation and spectator ions', 'A net ionic equation includes species that actually change. Keep soluble strong electrolytes separated into ions; retain solids intact.', 'Do not cancel ions that change chemical form.')], 'Mix aqueous AgNO₃ and NaCl. Write the net ionic precipitation equation.', ['AgCl forms an insoluble solid.', 'Na⁺ and NO₃⁻ remain unchanged in solution.'], 'Ag⁺(aq)+Cl⁻(aq)→AgCl(s).', 'In 2H₂+O₂→2H₂O, how many moles H₂O can 3 mol H₂ form with excess O₂?', '3 mol H₂O because the H₂:H₂O ratio is 1:1.'),
      l([t('Reaction mechanisms', 'Elementary steps must sum to the overall reaction. A proposed mechanism must also agree with the experimentally observed rate law.', 'Overall stoichiometric coefficients do not generally give rate-law exponents.'), t('Catalysts and reaction profiles', 'A catalyst provides a lower-activation-energy pathway and is regenerated. It speeds approach to equilibrium without changing K or ΔG°.', 'A catalyst does not shift the equilibrium composition.')], 'Doubling [A] while holding [B] fixed quadruples the initial rate. Find the order in A.', ['Write the rate factor as 2ᵐ.', 'Set 2ᵐ=4.'], 'Second order in A.', 'Why does increasing temperature usually increase reaction rate?', 'A larger fraction of collisions has energy sufficient to overcome the activation barrier.'),
      l([t('Hess’s law', 'Enthalpy is a state function. Reverse an equation and reverse ΔH; multiply an equation and multiply ΔH by the same factor.', 'Do not change a reaction without changing its enthalpy contribution.'), t('Bond-energy estimates', 'Estimate ΔH as energy required to break bonds minus energy released on forming bonds. Tabulated average bond energies are approximations.', 'Breaking bonds absorbs energy; forming bonds releases energy.')], 'Breaking reactant bonds requires 500 kJ/mol and forming product bonds releases 650 kJ/mol. Estimate ΔH.', ['Use bonds broken minus bonds formed.', 'Compute 500−650.'], '−150 kJ/mol; the reaction is exothermic.', 'If the solution warms in an insulated coffee-cup calorimeter, what is the sign of q for the reaction?', 'Negative, because the reaction transfers heat to the solution.'),
      l([t('Equilibrium expressions', 'Write K using equilibrium activities, approximated by concentrations or gas pressures in introductory problems. Pure solids and liquids are omitted.', 'Equilibrium means equal forward and reverse rates, not equal concentrations.'), t('Solubility equilibrium', 'Ksp relates dissolved ion concentrations through the dissolution stoichiometry. A common ion can reduce molar solubility.', 'Ksp and molar solubility are not generally the same number.')], 'For A⇌2B, Kc=4, [A]=1 M and [B]=1 M. Predict the initial direction.', ['Q=[B]²/[A]=1.', 'Q<K, so products are underrepresented relative to equilibrium.'], 'Net reaction proceeds toward B.', 'Does adding more pure solid to an existing heterogeneous equilibrium change K at fixed temperature?', 'No. K depends on temperature, and the solid’s activity is unchanged while that phase remains present.'),
      l([t('Acid strength and concentration', 'Strength describes degree of ionization, while concentration describes amount per volume. Ka compares acid dissociation tendencies.', 'A concentrated weak acid is not thereby a strong acid.'), t('pH and conjugate pairs', 'At 25°C, pH+pOH=14 for aqueous solutions. Conjugate acid-base pairs differ by one proton.', 'A smaller pH means greater hydrogen-ion concentration, not less.')], 'For a strong monoprotic acid with [H₃O⁺]=1.0×10⁻³ M, find pH.', ['Use pH=−log₁₀[H₃O⁺].', 'Take the negative logarithm of 10⁻³.'], 'pH=3.00.', 'At the half-equivalence point of a weak-acid/strong-base titration, how are pH and pKa related?', 'pH=pKa because the weak acid and its conjugate base have equal concentrations.'),
      l([t('Entropy and temperature', 'Use ΔG=ΔH−TΔS with consistent energy units. Temperature determines which term dominates when enthalpy and entropy effects compete.', 'A favorable ΔG does not imply a rapid reaction.'), t('Electrochemical cell accounting', 'Oxidation occurs at the anode and reduction at the cathode. For a galvanic cell, positive E° corresponds to negative ΔG°.', 'Do not multiply electrode potentials by stoichiometric coefficients.')], 'For ΔH=40 kJ/mol and ΔS=100 J/(mol·K), above what temperature is ΔG negative?', ['Convert entropy to 0.100 kJ/(mol·K).', 'Set ΔG=0, so T=40/0.100.'], 'Above 400 K under the stated approximation.', 'What connects standard free energy and equilibrium constant?', 'ΔG°=−RT ln K; K>1 corresponds to ΔG°<0.')
    ],
    apphys1: [
      l([t('Area under motion graphs', 'Area under velocity versus time is displacement; area under acceleration versus time is velocity change. Signed areas can cancel.', 'Distance requires adding magnitudes, not signed displacement areas.'), t('Projectile components', 'Ignoring drag, horizontal velocity is constant and vertical acceleration is downward. The components share the same elapsed time.', 'At the highest point, vertical velocity is zero but acceleration is not.')], 'A cart moves at +3 m/s for 2 s, then −2 m/s for 1 s. Find displacement and distance.', ['Signed displacement is 3(2)−2(1).', 'Distance adds the two positive path lengths.'], 'Displacement 4 m; distance 8 m.', 'What does a horizontal line on a velocity–time graph indicate?', 'Constant velocity and zero acceleration.'),
      l([t('Free-body diagrams', 'Draw only forces exerted on the chosen object. Resolve components along useful axes before applying ΣF=ma.', 'Velocity and acceleration are not forces to add to the diagram.'), t('Friction and circular motion', 'Static friction adjusts up to its maximum. Circular motion requires a net inward force supplied by real interactions.', 'Centripetal force is not an additional separate force.')], 'A 2 kg cart has 10 N rightward and 4 N leftward forces. Find acceleration.', ['Net force is 6 N to the right.', 'Use a=Fnet/m.'], '3 m/s² to the right.', 'Can an object move at constant speed while accelerating?', 'Yes. Its velocity direction changes in circular motion.'),
      l([t('Work and kinetic energy', 'Net work equals change in kinetic energy. For constant force, work is Fd cos θ; a perpendicular force does no work.', 'A force can be nonzero while doing zero work.'), t('Power', 'Average power is energy transferred per time. For a force parallel to velocity, instantaneous power is Fv.', 'Energy and power have different units: joules and watts.')], 'A net force does 12 J of work on a cart initially with 5 J kinetic energy. Find final kinetic energy.', ['Apply Wnet=Kf−Ki.', 'Add 12 J to the initial 5 J.'], '17 J.', 'If speed doubles at fixed mass, what happens to kinetic energy?', 'It quadruples because K=½mv².'),
      l([t('Collision classification', 'Momentum is conserved for a system with negligible external impulse. Kinetic energy is conserved only in elastic collisions.', 'Objects sticking together does not mean momentum is lost.'), t('Impulse graphs', 'Impulse is the signed area under a force–time graph. Increasing collision duration can reduce average force for the same momentum change.', 'Peak force and average force are not generally equal.')], 'A 2 kg cart at 3 m/s sticks to a stationary 1 kg cart. Find final velocity.', ['Initial momentum is 6 kg·m/s.', 'Set combined mass 3 kg times final velocity equal to 6.'], '2 m/s in the initial direction.', 'A 4 N force acts for 0.5 s. What impulse does it deliver?', '2 N·s in the force direction.'),
      l([t('Rotational acceleration', 'For a rigid body about a fixed axis, net torque equals Iα. Torque sign follows the chosen rotation convention.', 'Equal forces can produce different torques at different lever arms.'), t('Static equilibrium', 'A body in static equilibrium has both zero net force and zero net torque. Choose a torque origin that eliminates unknown forces when possible.', 'Zero net force alone does not prevent angular acceleration.')], 'A 10 N perpendicular force acts 0.30 m from a pivot. Find torque magnitude.', ['Use τ=rF sin θ.', 'With θ=90°, sin θ=1.'], '3.0 N·m.', 'How does moving mass farther from the axis affect rotational inertia?', 'It increases rotational inertia because contributions scale with squared distance.'),
      l([t('Rotational kinetic energy', 'A rotating rigid body has Krot=½Iω². A rolling object can also have translational kinetic energy ½mv².', 'Rolling kinetic energy is not just the translational part.'), t('Conservation of angular momentum', 'Angular momentum stays constant when net external torque is zero. Internal changes can alter I and ω while their product remains fixed about a fixed axis.', 'Conserving angular momentum does not automatically conserve kinetic energy.')], 'A skater halves rotational inertia with negligible external torque. What happens to angular speed?', ['Set Iiωi=Ifωf.', 'Substitute If=Ii/2.'], 'Angular speed doubles.', 'For rolling without slipping, how are center-of-mass speed and angular speed related?', 'v=Rω.'),
      l([t('Period relationships', 'An ideal spring oscillator has T=2π√(m/k). A small-angle pendulum has T=2π√(L/g).', 'In these ideal models, increasing amplitude does not change the period.'), t('Phase and energy exchange', 'At an oscillator’s equilibrium position speed is greatest. At turning points speed is zero and potential energy is greatest.', 'Acceleration is largest in magnitude at maximum displacement, not at equilibrium.')], 'A spring oscillator’s mass is quadrupled while k stays fixed. How does its period change?', ['Period depends on the square root of mass.', '√4=2.'], 'The period doubles.', 'At the turning point of ideal spring motion, is the restoring force zero?', 'No. Its magnitude is greatest because displacement is greatest.'),
      l([t('Hydrostatic pressure', 'Fluid pressure increases with depth by ρgh. At the same depth in a connected static fluid, pressure is equal.', 'Container shape does not by itself change pressure at a given depth.'), t('Bernoulli reasoning', 'For steady ideal flow along a streamline, pressure, kinetic, and gravitational energy terms trade off. State assumptions before applying the relation.', 'Higher speed implies lower pressure only when other relevant terms are controlled.')], 'Water flows through a pipe that narrows to half its area. What happens to speed for steady incompressible flow?', ['Use A₁v₁=A₂v₂.', 'Set A₂=A₁/2.'], 'The speed doubles.', 'What determines the buoyant force on a fully submerged object?', 'The weight of displaced fluid, ρfluid g Vdisplaced.')
    ],
    apenvs: [
      l([t('Trophic energy budgets', 'Net primary productivity equals gross productivity minus producer respiration. Only part of production transfers to the next trophic level.', 'Energy flows through ecosystems; matter cycles.'), t('Nitrogen transformations', 'Nitrogen fixation converts atmospheric N₂ to biologically usable forms. Nitrification and denitrification move nitrogen among other chemical forms.', 'Most plants cannot directly use atmospheric N₂.')], 'An ecosystem has GPP=2000 and producer respiration=1200 kcal/m²/year. Find NPP.', ['Subtract respiration from gross productivity.', 'Keep the area and time units.'], '800 kcal/m²/year.', 'Why are upper trophic levels generally supported by less energy?', 'Energy is used in metabolism and lost as heat, and not all biomass is consumed or assimilated.'),
      l([t('Genetic, species, and ecosystem diversity', 'Biodiversity exists at several scales. Species richness counts species; evenness describes how evenly individuals are distributed.', 'Two habitats with equal richness can have very different evenness.'), t('Habitat fragmentation', 'Fragmentation reduces connected habitat and increases edge effects. Corridors can support movement and gene flow but require context-specific design.', 'A protected area’s size alone does not determine its ecological value.')], 'Two habitats each contain four species, but one is dominated by a single species. Compare diversity components.', ['Both have equal species richness.', 'The dominated habitat has lower evenness.'], 'Richness is equal; community evenness differs.', 'Why can small isolated populations lose genetic diversity?', 'Genetic drift and limited gene flow can remove alleles over generations.'),
      l([t('Human population structure', 'Age-structure diagrams reveal the relative sizes of younger and older cohorts. A broad young base can sustain growth even as birth rates decline.', 'Population momentum means growth need not stop immediately.'), t('Growth calculations', 'Net population change equals births plus immigration minus deaths and emigration. Percent growth divides net change by starting population.', 'Birth rate alone is not the population growth rate.')], 'A town starts with 1000 people, then has 20 births, 10 deaths, 15 arrivals, and 5 departures. Find growth.', ['Net change=20−10+15−5=20.', 'Divide 20 by 1000 and multiply by 100.'], '2% growth; final population 1020.', 'What distinguishes density-dependent from density-independent limiting factors?', 'Density-dependent effects strengthen with crowding; density-independent disturbances need not depend on population density.'),
      l([t('Plate boundaries', 'Divergent boundaries create crust; convergent boundaries can subduct or uplift crust; transform boundaries involve lateral motion.', 'Earthquakes can occur at multiple boundary types.'), t('Watersheds and infiltration', 'A watershed drains to a common outlet. Vegetation and permeable soil increase infiltration; impervious surfaces increase runoff.', 'A groundwater aquifer is not simply an underground lake.')], 'A parking lot replaces a vegetated field. Predict storm runoff.', ['Pavement reduces infiltration into soil.', 'More precipitation moves rapidly across the surface.'], 'Runoff volume and peak stream flow are likely to increase.', 'Why can removing topsoil reduce agricultural productivity?', 'Topsoil contains much of the organic matter, nutrients, and biologically active structure that supports crops.'),
      l([t('Agricultural tradeoffs', 'Irrigation supports yields but can deplete water supplies and accumulate salts. Soil conservation practices reduce erosion and nutrient loss.', 'Higher short-term yield is not the same as long-term sustainability.'), t('Resource management', 'Sustainable harvest must consider renewal rates, habitat effects, and uncertainty. Rules can align individual incentives with shared-resource protection.', 'A renewable resource can still be depleted faster than it recovers.')], 'Why can overirrigation in a dry climate cause salinization?', ['Irrigation water contains dissolved salts.', 'Evaporation removes water while leaving salts behind.'], 'Salt accumulates in soil and can impair water uptake by crops.', 'How does contour plowing reduce erosion?', 'Rows follow elevation contours, slowing runoff and reducing soil transport downhill.'),
      l([t('Energy conversions', 'Efficiency is useful energy output divided by total input. Track units through conversions between energy, power, and time.', 'A kilowatt-hour measures energy, not instantaneous power.'), t('Renewable-energy constraints', 'Solar and wind availability varies with location and time; storage, transmission, and demand management affect reliability.', 'Renewable does not mean impact-free or available at every moment.')], 'A device uses 1000 J and produces 300 J of useful output. Find efficiency.', ['Divide useful output by input.', 'Multiply 0.30 by 100.'], '30%.', 'How much energy does a 2 kW heater use in 3 hours?', '6 kWh.'),
      l([t('Primary and secondary pollutants', 'Primary pollutants are emitted directly; secondary pollutants form through atmospheric reactions. Ground-level ozone is a secondary pollutant.', 'Protective stratospheric ozone and harmful ground-level ozone occur in different contexts.'), t('Acid deposition', 'Sulfur dioxide and nitrogen oxides can form acids in the atmosphere. Acidification can leach nutrients and mobilize toxic metals.', 'Acid rain is not caused primarily by the same mechanism as greenhouse warming.')], 'Why can sunny conditions worsen photochemical smog?', ['Sunlight drives reactions involving nitrogen oxides and volatile organic compounds.', 'Those reactions can produce ground-level ozone.'], 'Greater sunlight can promote secondary ozone formation when precursors are present.', 'What does a temperature inversion do to local pollution?', 'It suppresses vertical mixing and can trap pollutants near the ground.'),
      l([t('Dose and exposure', 'Risk depends on toxicity and exposure, including dose, duration, and route. Persistence influences how long a contaminant remains available.', 'Hazard alone does not specify actual exposure risk.'), t('Wastewater treatment', 'Primary treatment physically removes solids; secondary treatment uses biological processes to reduce organic matter. Further treatment can target nutrients or pathogens.', 'Removing visible solids does not make water free of dissolved contaminants.')], 'Fertilizer runoff enters a lake. Explain how it can lead to fish deaths.', ['Added nutrients stimulate algal growth.', 'Decomposition consumes dissolved oxygen after organisms die.'], 'Low dissolved oxygen can suffocate fish and other aquatic organisms.', 'How do bioaccumulation and biomagnification differ?', 'Bioaccumulation increases concentration within an organism over time; biomagnification increases it across trophic levels.'),
      l([t('Climate feedbacks', 'Loss of reflective ice lowers albedo and increases absorbed sunlight. This positive feedback amplifies the initial warming.', 'A feedback amplifies or dampens a change; it is distinct from the initial forcing.'), t('Ozone depletion', 'Certain chlorine- and bromine-containing compounds catalyze stratospheric ozone destruction, increasing surface UV exposure.', 'The ozone hole is not the main cause of global warming.')], 'Explain why dissolving more CO₂ in seawater can harm calcifying organisms.', ['Dissolved CO₂ changes carbonate chemistry and increases hydrogen-ion concentration.', 'Carbonate availability can decline, making calcium carbonate construction more difficult.'], 'Shell and skeleton formation can become more energetically difficult as ocean chemistry changes.', 'Is sea-level rise caused only by melting floating sea ice?', 'No. Thermal expansion and melting land ice are major contributors; floating sea ice has little direct effect.')
    ],
    apush: [
      l([t('Regional Indigenous adaptation', 'Indigenous societies developed varied economies and political structures shaped by environments, agriculture, trade, and cultural choices. Compare specific regions rather than treating them as one society.', 'Do not assume all Indigenous communities were nomadic or politically alike.'), t('Columbian Exchange', 'Atlantic contact moved crops, animals, pathogens, and people between continents. Epidemic disease and coercive labor transformed Indigenous populations and colonial economies.', 'Exchange does not imply equal benefits or voluntary participation.')], 'Explain one way maize cultivation supported complex societies before European contact.', ['Cultivation could produce food surpluses.', 'Surpluses supported settled communities, population growth, and specialized labor.'], 'Agricultural production helped sustain larger settlements and more differentiated social and political organization.', 'Why did epidemic disease have such devastating effects after contact?', 'Many Indigenous populations lacked prior exposure to newly introduced pathogens, while conquest and displacement intensified harm.'),
      l([t('Colonial labor systems', 'Chesapeake tobacco production initially relied heavily on indentured labor before expanding racial slavery. Plantation economies linked colonial production to Atlantic markets.', 'Labor systems changed over time; do not project a later arrangement onto every colony.'), t('Regional institutions', 'New England town life, Middle Colony commerce, and plantation regions developed different economies and institutions within a shared imperial system.', 'Regional comparisons require evidence, not stereotypes about all colonists.')], 'Why did plantation slavery expand in the Chesapeake?', ['Identify labor demand from export agriculture.', 'Connect legal changes and racial hierarchy to a more permanent, inheritable labor system.'], 'Planters increasingly used enslaved labor while colonial laws entrenched racial and hereditary enslavement.', 'How did mercantilist policies connect colonies to Britain?', 'They directed colonial trade and production toward imperial economic goals through rules such as navigation restrictions.'),
      l([t('Imperial crisis after 1763', 'British efforts to raise revenue and tighten control after the Seven Years’ War intensified disputes over colonial representation and authority.', 'The war’s end did not itself make independence inevitable.'), t('Articles and Constitution', 'Weak national revenue and enforcement powers under the Articles informed constitutional debates. Federalists and Anti-Federalists disagreed over power and protection of rights.', 'Opposition to ratification was not simply opposition to all government.')], 'Explain how taxation disputes contributed to the Revolution.', ['Britain sought colonial revenue after an expensive war.', 'Colonists challenged Parliament’s authority to tax them without direct representation.'], 'Fiscal measures became a constitutional conflict over legitimate political authority.', 'Why did a promised Bill of Rights help ratification?', 'It addressed fears that a stronger national government could threaten individual liberties.'),
      l([t('Market revolution', 'Transportation, commercial agriculture, and industrial production linked regions and altered labor, family life, and exchange. Benefits and costs varied by class, gender, and region.', 'Economic growth did not erase coercion or inequality.'), t('Reform and exclusion', 'Religious revival and democratic ideals fueled abolition, temperance, education, and women’s rights activism, while expansion displaced Indigenous peoples.', 'Expanded voting rights for white men did not mean universal democracy.')], 'Connect canal development to the market revolution.', ['Canals lowered transport costs between inland producers and markets.', 'Lower costs encouraged commercial production and wider exchange.'], 'Transportation improvements helped households and regions become more integrated into market networks.', 'What contradiction did removal policy expose in Jacksonian democracy?', 'Political participation expanded for many white men while Indigenous sovereignty and rights were violently restricted.'),
      l([t('Slavery and territorial expansion', 'New western territory repeatedly reopened disputes about slavery’s expansion, political representation, and federal authority, undermining sectional compromise.', 'States’ rights claims must be connected to the specific issue of slavery.'), t('Reconstruction’s gains and limits', 'The Reconstruction Amendments abolished slavery and defined citizenship and voting protections, while organized violence and weakening enforcement constrained their implementation.', 'Formal legal change and lived equality are different measures.')], 'How did the Mexican–American War intensify sectional conflict?', ['The war added extensive territory to the United States.', 'Political leaders disputed whether slavery would expand into that territory.'], 'Territorial acquisition increased conflict over slavery and the balance of sectional power.', 'What did the Fourteenth Amendment establish?', 'National citizenship for people born or naturalized in the United States and protections including due process and equal protection.'),
      l([t('Corporate consolidation and labor', 'Industrial corporations used consolidation and economies of scale, while workers organized against low pay, unsafe conditions, and weak bargaining power.', 'Industrial output alone does not reveal workers’ living conditions.'), t('Migration and western expansion', 'Immigration, internal migration, railroads, and federal policy reshaped cities and the West, often dispossessing Indigenous peoples and intensifying racial exclusion.', 'Do not frame western land as unoccupied before settlement.')], 'Explain one reason industrial workers formed unions.', ['Large employers could set wages and conditions for many individual workers.', 'Collective action sought greater bargaining power over those terms.'], 'Union organization attempted to counter unequal bargaining power and improve pay, hours, or safety.', 'How did the Chinese Exclusion Act reflect a limit of opportunity?', 'It imposed nationality-based immigration exclusion amid anti-Chinese racism and labor competition claims.'),
      l([t('New Deal and federal responsibility', 'New Deal programs expanded federal relief, regulation, and social insurance during the Depression, but excluded or unevenly served many groups.', 'The New Deal did not abolish capitalism or end every form of inequality.'), t('War mobilization and rights', 'World wars expanded federal authority and employment opportunities while also producing restrictions on dissent and civil liberties, including Japanese American incarceration during WWII.', 'National unity rhetoric does not prove equal treatment.')], 'Compare the New Deal with earlier limited-government expectations.', ['Use Social Security or financial regulation as concrete evidence.', 'Explain how the policy made national government more directly responsible for economic security.'], 'The New Deal enlarged federal responsibility while retaining private enterprise and facing political and constitutional limits.', 'Why is wartime incarceration of Japanese Americans important in a rights argument?', 'It shows how national-security claims and racial prejudice curtailed civil liberties during mobilization.'),
      l([t('Containment and Cold War intervention', 'Containment sought to limit Soviet influence through aid, alliances, and military action. Different interventions had distinct local contexts and consequences.', 'Not every anticolonial movement was simply directed by Moscow.'), t('Civil rights and federal action', 'Grassroots organizing, litigation, and protest pressured federal institutions to address segregation and voting discrimination. Legal victories required continued enforcement.', 'Court decisions alone did not automatically end discrimination.')], 'Explain how civil rights activism and federal policy interacted.', ['Identify an organizing tactic such as boycotts or voting-rights marches.', 'Connect public pressure and documented injustice to legislation or enforcement.'], 'Activism helped compel federal action, including the Civil Rights Act and Voting Rights Act, while implementation remained contested.', 'How did the Vietnam War affect domestic trust in government?', 'The prolonged war, casualties, and gaps between official claims and events fueled protest and skepticism.'),
      l([t('Conservative political mobilization', 'Late-twentieth-century conservatism combined concerns about taxes, regulation, social change, and national power, though its coalitions contained different priorities.', 'A political coalition is not ideologically uniform.'), t('Globalization and technological change', 'Trade, deindustrialization, immigration, and digital technology reshaped employment and communities, creating new opportunities and uneven regional effects.', 'National economic growth can coexist with local economic decline.')], 'Explain how deindustrialization could change political demands in a community.', ['Factory closures reduce jobs and local tax revenue.', 'Affected residents may seek protection, retraining, or new investment.'], 'Economic restructuring can reshape priorities and dissatisfaction without producing one inevitable political response.', 'What major international change followed the Soviet Union’s collapse?', 'The Cold War’s bipolar rivalry ended, changing U.S. strategic priorities and global power relationships.')
    ],
    apworld: [
      l([t('Song China and state institutions', 'Song rulers used a Confucian bureaucracy and examinations alongside a commercial economy. State legitimacy and economic innovation interacted with social hierarchy.', 'Examinations did not create equal opportunity for every social group.'), t('Regional state-building comparisons', 'States such as Mali and the Inca used distinct combinations of trade, tribute, religion, administration, and infrastructure to sustain authority.', 'A comparison should explain a shared process as well as a difference.')], 'Compare a trade-based source of power in Mali with an administrative source in Song China.', ['Mali benefited from trans-Saharan commerce and control of valuable resources.', 'Song governance relied on a trained bureaucracy and examination traditions.'], 'Both organized resources to support rule, but commercial routes and bureaucratic recruitment supplied different mechanisms.', 'Why is c.1200–1450 not simply a story of European expansion?', 'Major states and networks across Africa, Asia, and the Americas developed independently of later European maritime dominance.'),
      l([t('Indian Ocean commerce', 'Monsoon patterns, maritime technology, and merchant diasporas supported Indian Ocean exchange. Ports connected goods, religions, and cultural practices.', 'Trade networks carried ideas and pathogens as well as commodities.'), t('Mongol connectivity', 'Mongol conquest caused destruction but also linked large regions through protected routes and diplomatic exchange, facilitating movement across Eurasia.', 'The effects of empire can include both disruption and integration.')], 'Explain how monsoon knowledge supported Indian Ocean trade.', ['Seasonal wind changes made routes more predictable.', 'Merchants could schedule outward and return voyages around those patterns.'], 'Environmental knowledge reduced uncertainty and supported repeated long-distance maritime exchange.', 'How did exchange networks contribute to the spread of the Black Death?', 'Travel and trade moved infected people, animals, and disease vectors across connected regions.'),
      l([t('Imperial administration', 'Ottoman, Mughal, Safavid, and Qing rulers combined military power with taxation, bureaucracy, and strategies for managing diverse populations.', 'Gunpowder alone cannot explain durable imperial control.'), t('Religious legitimation', 'Rulers used religious institutions and monumental art to justify authority, while religious differences could also generate conflict within or between empires.', 'Religious policy varied across rulers and periods within the same empire.')], 'Explain why an empire needs more than military conquest to endure.', ['Conquest establishes control but does not automatically provide stable revenue.', 'Administration and negotiated relationships help govern conquered populations.'], 'Durable rule requires systems for taxation, legitimacy, and local cooperation as well as force.', 'Why can comparing Mughal religious policies across rulers be more useful than one blanket claim?', 'Policies changed; comparing specific rulers avoids treating a long-lived empire as unchanging.'),
      l([t('Coerced Atlantic labor', 'Plantation demand expanded the transatlantic slave trade, reshaping African societies and American economies through forced migration and racialized exploitation.', 'Enslaved people were historical actors who resisted, not merely units of labor.'), t('Silver and global exchange', 'American silver connected European empires, Asian markets, and coerced labor systems. Demand in China helped sustain transoceanic flows.', 'Early globalization was not exclusively an Atlantic process.')], 'Link American silver production to Asian trade.', ['Spanish-controlled mines supplied large quantities of silver.', 'Silver moved through trade routes toward markets where it was highly demanded, including China.'], 'Mining in the Americas became connected to Asian commercial and fiscal systems.', 'What distinguishes the Columbian Exchange from a single trade route?', 'It describes broad biological and human transfers across hemispheres, not just commercial exchange between two ports.'),
      l([t('Enlightenment and revolution', 'Ideas about rights and popular sovereignty challenged inherited authority, but revolutionary movements applied those principles unevenly across race, class, and gender.', 'Shared ideals did not produce identical outcomes in every revolution.'), t('Industrial transformation', 'Mechanization, fossil fuels, capital, labor supply, and market access combined to expand industrial production and alter social relations.', 'No single invention explains the entire Industrial Revolution.')], 'How did the Haitian Revolution both use and expand revolutionary ideals?', ['It challenged colonial authority using claims to liberty.', 'Enslaved revolutionaries made emancipation central to that claim.'], 'It exposed the limits of revolutions that proclaimed rights while preserving slavery.', 'Why distinguish political from industrial revolutions?', 'One transforms authority and citizenship; the other transforms production, though they can influence each other.'),
      l([t('Imperial motives and resistance', 'Industrial states sought resources, markets, strategic advantage, and prestige; colonized peoples resisted through armed struggle, diplomacy, and cultural adaptation.', 'Imperial justifications should not be accepted as neutral descriptions.'), t('Labor migration', 'Industrial and imperial economies encouraged migration through wage incentives, coercion, and unequal opportunity, creating diasporas and new racial restrictions.', 'Migration was not always freely chosen or permanent.')], 'Explain one economic connection between industrialization and imperial expansion.', ['Factories needed raw materials and access to buyers.', 'Imperial control could secure supplies or shape trade rules.'], 'Industrial demand strengthened incentives for territorial control and economic domination.', 'Why should a source praising a “civilizing mission” be contextualized?', 'Its language can legitimize unequal rule and obscure extraction, coercion, and colonized perspectives.'),
      l([t('Total war', 'World wars mobilized civilian economies, propaganda, and state power on an enormous scale. Civilian suffering and colonial participation were central, not peripheral.', 'Combat statistics alone do not capture total war’s social effects.'), t('Interwar crisis and authoritarianism', 'Economic instability, postwar grievances, and weak institutions created openings for authoritarian movements, but outcomes differed across societies.', 'Depression did not automatically produce fascism everywhere.')], 'Explain how total war changed civilian life.', ['Governments redirected production and labor toward military needs.', 'Rationing, propaganda, displacement, and bombing affected civilians directly.'], 'The boundary between battlefield and home front became less distinct.', 'Why connect the Great Depression to global trade and finance?', 'International economic links transmitted shocks across national boundaries.'),
      l([t('Decolonization pathways', 'Independence resulted from local organizing, war, negotiation, and changing imperial capacity. New states confronted inherited borders and economic dependencies.', 'Political independence did not instantly remove colonial legacies.'), t('Cold War alignment', 'Superpowers competed through alliances, aid, and proxy conflicts; some new states pursued nonalignment to protect autonomy.', 'Nonaligned states were not necessarily isolated from either bloc.')], 'Why might a newly independent state reject formal Cold War alignment?', ['Alignment could bring aid but constrain policy choices.', 'Leaders might seek autonomy and support from multiple partners.'], 'Nonalignment could be a strategy for bargaining and independent development.', 'How could decolonization and the Cold War overlap?', 'Local independence struggles could become arenas for superpower funding, intervention, and ideological competition.'),
      l([t('Global production and inequality', 'Transnational firms distribute production across borders, linking labor markets and consumers. Benefits and vulnerabilities are unevenly distributed.', 'Cheaper consumer goods do not reveal all labor or environmental costs.'), t('Cultural exchange and resistance', 'Mass media and migration spread cultural practices, while communities adapt or resist them. Globalization can encourage hybrid identities as well as backlash.', 'Globalization does not simply erase every local culture.')], 'Explain how a global supply chain creates both efficiency and vulnerability.', ['Specialization can lower costs and connect distant producers.', 'Disruption at one important node can delay production elsewhere.'], 'Interdependence supports efficiency but can transmit shocks across borders.', 'Why can global environmental problems require international cooperation?', 'Emissions and ecological effects cross borders, while costs and benefits are shared unevenly.')
    ],
    apeuro: [
      l([t('Humanism and patronage', 'Renaissance humanists studied classical texts and human experience; patrons used art and scholarship to express wealth, civic identity, and authority.', 'Humanism was not uniformly secular or opposed to Christianity.'), t('Commercial and maritime expansion', 'State competition, trade ambitions, navigation, and finance supported overseas expansion, with profound effects on labor, wealth, and colonized peoples.', 'Exploration narratives should include conquest and coercive labor.')], 'Explain how patronage shaped Renaissance art.', ['Patrons supplied resources and commissioned particular subjects.', 'Artists’ work could communicate the patron’s status or political message.'], 'Artistic production reflected both creative innovation and relationships of power and funding.', 'Why did classical learning appeal to humanists?', 'It offered models of rhetoric, civic life, history, and ethics for examining contemporary human affairs.'),
      l([t('Print and religious debate', 'Printing accelerated the circulation of religious arguments, making disputes over doctrine and authority accessible to larger audiences.', 'Technology spread competing ideas; it did not dictate one interpretation.'), t('Confessional states and reform', 'Protestant and Catholic authorities reorganized institutions, education, and religious practice. Rulers’ political interests interacted with theological commitments.', 'The Reformation was not a single unified Protestant movement.')], 'Explain how printing contributed to the spread of reform ideas.', ['Printed pamphlets could be reproduced and distributed beyond local audiences.', 'Wider circulation enabled repeated debate and mobilization.'], 'Print expanded the reach and speed of religious controversy.', 'How did the Catholic Reformation respond to challenges?', 'It combined doctrinal reaffirmation with institutional reform, education, and renewed religious activity.'),
      l([t('Parliamentary constraints', 'English political conflict strengthened parliamentary limits on monarchy, especially after the Glorious Revolution, while leaving substantial social exclusions.', 'Constitutional monarchy did not mean universal democratic participation.'), t('Absolutist state-building', 'Monarchs such as Louis XIV expanded administration and military capacity while managing elites through patronage and court culture.', 'Absolutism describes ambitions and institutions, not unlimited practical control.')], 'Compare an absolutist and a constitutional approach to taxation.', ['An absolutist ruler sought greater centralized control over revenue.', 'A constitutional arrangement placed more formal constraints through representative institutions.'], 'Both needed revenue, but authority to secure it was organized differently.', 'Why did courts such as Versailles matter politically?', 'They concentrated elite competition and patronage around the monarch and helped manage aristocratic influence.'),
      l([t('Scientific methods', 'Observation, mathematical explanation, and experimentation challenged inherited accounts of nature. New methods developed through debate rather than one instant break.', 'Science did not eliminate religious belief among all practitioners.'), t('Enlightenment political thought', 'Thinkers debated reason, rights, toleration, sovereignty, and economic organization. Their proposals differed and often contained exclusions.', 'Do not treat every Enlightenment thinker as advocating identical democracy.')], 'Explain how empirical investigation differed from relying only on inherited authority.', ['Investigators tested claims against observations or experiments.', 'Evidence could challenge an accepted explanation.'], 'Knowledge claims increasingly required demonstrable support rather than authority alone.', 'How could an “enlightened absolutist” combine reform and monarchy?', 'A ruler could adopt administrative or legal reforms while retaining centralized political power.'),
      l([t('Revolutionary radicalization', 'Fiscal crisis, political exclusion, war, and popular mobilization shaped the French Revolution’s changing goals and institutions.', 'Do not treat 1789 and the Terror as politically identical moments.'), t('Napoleon and restoration', 'Napoleonic rule spread legal and administrative reforms while concentrating power; postwar settlement sought stability and a balance of power.', 'Napoleon preserved some revolutionary changes while reversing others.')], 'Explain one continuity and one change under Napoleon.', ['The Civil Code preserved important legal reforms and property protections.', 'Authoritarian rule limited political participation and dissent.'], 'Legal and administrative reform continued alongside a return to concentrated executive power.', 'What was a central goal of the Congress of Vienna?', 'To restore stability and contain renewed upheaval through a European balance of power and restored dynasties.'),
      l([t('Industrial class relations', 'Factory production and urbanization altered work discipline, family economies, and class identities, encouraging labor organization and demands for reform.', 'Industrialization’s effects differed by gender, occupation, and location.'), t('Ideological responses', 'Liberalism, socialism, and conservatism offered different responses to industrial and political change, each containing internal disagreements.', 'A reform proposal’s label is less useful than its specific goals and constituency.')], 'Why did industrialization encourage demands for labor regulation?', ['Factory work concentrated workers under new schedules and hazards.', 'Public criticism and organization challenged long hours and unsafe conditions.'], 'Social and political pressure pushed governments toward limits on exploitation, though reforms were uneven.', 'What is one difference between liberal and socialist critiques of nineteenth-century society?', 'Liberals often emphasized legal freedoms and markets; socialists emphasized ownership, class inequality, and collective economic arrangements.'),
      l([t('Nationalism and unification', 'Nationalist movements connected cultural identity to political sovereignty. Italian and German unification combined popular ideas with diplomacy and state power.', 'Unification was not only a spontaneous popular movement.'), t('Imperialism and mass politics', 'European states expanded empires while widening political mobilization at home, using nationalism, racial ideology, and strategic competition to justify rule abroad.', 'Domestic political inclusion could coexist with colonial exclusion.')], 'Explain why German unification illustrates both nationalism and statecraft.', ['National identity supplied a framework for political unity.', 'Prussian leadership used diplomacy and military victories to shape the outcome.'], 'Ideas of nationhood and strategic state action worked together.', 'How could mass newspapers influence politics?', 'They broadened access to political messages and helped mobilize publics, while also spreading propaganda and stereotypes.'),
      l([t('War and regime collapse', 'World War I strained economies, armies, and political legitimacy, contributing to revolution and the collapse of several empires.', 'A wartime collapse usually has multiple military, economic, and political causes.'), t('Fascism, Stalinism, and genocide', 'Authoritarian regimes used coercion, propaganda, and institutional control in distinct ideological projects. Nazi racial ideology and state violence culminated in the Holocaust.', 'Comparisons must preserve important differences rather than equating all regimes.')], 'How could economic crisis weaken a democratic regime?', ['Unemployment and insecurity can undermine confidence in existing institutions.', 'Antidemocratic movements can promise decisive solutions and target scapegoats.'], 'Crisis can create openings for authoritarian mobilization, though its success depends on political choices and institutions.', 'Why is the Holocaust not adequately explained as an accidental consequence of war?', 'It resulted from deliberate antisemitic persecution and systematic mass murder carried out by the Nazi regime and collaborators.'),
      l([t('European integration', 'Postwar cooperation aimed to reduce conflict and coordinate economic interests, eventually developing shared institutions with continuing debates over sovereignty.', 'Integration has been contested and uneven, not a simple disappearance of national states.'), t('Cold War division and social change', 'Europe experienced rival political-economic systems, welfare-state development, migration, and rights movements, followed by major transformations after communist regimes fell.', 'Western and Eastern European experiences were not internally uniform.')], 'Why could economic integration support postwar peace?', ['Shared production and trade interests raised the costs of conflict.', 'Institutions created repeated opportunities for negotiation.'], 'Economic interdependence and institutional cooperation offered ways to manage rivalry.', 'What changed in Europe after 1989?', 'Communist regimes collapsed across much of Eastern Europe, Germany reunified, and new debates emerged over markets, borders, and integration.')
    ],
    apgov: [
      l([t('Enumerated and implied powers','Enumerated powers are written in the Constitution. Implied powers provide means of carrying them out through the necessary and proper clause.','Implied does not mean unlimited.'),t('Federalism and supremacy','National and state governments share governing authority. Valid federal law prevails over conflicting state law under the supremacy clause.','Separate levels of government are different from separate branches.')],'Congress creates an institution to help administer a listed financial power. What constitutional reasoning could support it?',['Identify the enumerated financial power.','Explain why the institution is a means of executing that power.'],'An implied-power argument connects the means to an enumerated end.','How does separation of powers differ from federalism?','Separation divides authority among branches; federalism divides it between national and state governments.'),
      l([t('Oversight tools and executive accountability','Congress can hold hearings, investigate implementation, and control appropriations to monitor the executive branch. Explain the tool and its effect.','Passing a statute is not the only congressional check.'),t('Judicial review and precedent','Courts resolve legal disputes and can invalidate unconstitutional government action. Precedent guides later decisions but may be distinguished or overturned.','Courts do not routinely initiate legislation.')],'An agency implements a law in a way legislators oppose. Identify two congressional responses.',['A hearing can investigate the agency’s interpretation.','An appropriations decision or revised statute can constrain implementation.'],'Oversight gathers information; legislative and budget authority can change incentives or rules.','Does divided government necessarily prevent every law from passing?','No. It may make agreement harder, but negotiation and coalitions can still produce legislation.'),
      l([t('Liberties and equality','Civil liberties protect freedoms from government interference. Civil rights concern equal treatment and protection against discrimination.','A policy dispute can involve both categories.'),t('Incorporation and the Fourteenth Amendment','Selective incorporation applies many Bill of Rights protections to states through the Fourteenth Amendment’s due process clause. Equal protection addresses unequal treatment.','The two clauses serve different constitutional arguments.')],'A prompt asks why a state action must respect a federal free-speech protection. Build the connection.',['Identify the relevant First Amendment freedom.','Explain its application to states through incorporation.'],'Connect the freedom, the state action, and the constitutional doctrine rather than naming amendments alone.','Which clause is central to an argument about unequal state treatment?','The Fourteenth Amendment’s equal protection clause.'),
      l([t('Cohort effects and political learning','Family, schools, media, and formative events shape political beliefs. A cohort effect reflects shared experiences of a generation; a life-cycle effect reflects changes as people age.','Demographic tendencies do not determine an individual’s beliefs.'),t('Poll design and uncertainty','A representative sampling method, neutral wording, and an appropriate target population matter. Sampling error does not account for every source of bias.','A large voluntary-response poll can remain unrepresentative.')],'An online poll lets any visitor vote repeatedly. Why is its candidate estimate weak?',['Participation is self-selected rather than randomly sampled.','Repeat responses can further distort representation.'],'The percentage cannot reliably represent all voters.','Does a narrow margin of error eliminate wording bias?','No. Sampling uncertainty and question-wording bias are different problems.'),
      l([t('Turnout and mobilization','Voting costs, registration rules, interest, and mobilization can affect participation. Distinguish eligible voters from registered voters when interpreting turnout.','Different denominators can produce different turnout percentages.'),t('Plurality elections and parties','A winner-take-all contest awards the seat to the leading candidate. Voters and organizations may coordinate around competitive parties to avoid splitting support.','Plurality does not require more than half of all votes.')],'Candidates receive 42%, 35%, and 23% in a single-seat plurality contest. Who wins?',['Find the largest vote share.','Check whether the rule requires a majority or only a plurality.'],'The 42% candidate wins under plurality rules.','Why can an interest group influence policy without running a candidate?','It can lobby, litigate, provide information, and mobilize supporters around an issue.')
    ],
    aphug: [
      l([t('Scale and aggregation','A pattern visible nationally may differ across regions or neighborhoods. State the spatial scale before explaining a relationship.','An area average does not describe every person in it.'),t('Map projection tradeoffs','Representing a spherical surface on a plane distorts area, shape, distance, or direction. Choose a projection for the map’s purpose.','No flat world map preserves all properties.')],'A country has rising average income while one region declines. Are the findings contradictory?',['Identify the national and regional scales.','An aggregate can rise while one component falls.'],'Both can be true; aggregation conceals internal variation.','Why might an equal-area map help compare agricultural land?','It preserves relative area, making spatial extent comparisons more appropriate.'),
      l([t('Migration mechanisms','Push factors encourage departure; pull factors attract people elsewhere. Intervening obstacles can prevent a desired move.','A motive alone does not determine whether migration occurs.'),t('Demographic transition and population momentum','Changes in mortality and fertility alter growth and age structure. Population momentum can continue after fertility falls.','The model is a framework, not a fixed timetable for every country.')],'A region’s death rate falls before its birth rate. Explain the population effect.',['The difference between births and deaths widens.','Natural increase rises, holding migration constant.'],'Population growth accelerates during that interval.','How does a dependency ratio relate to age structure?','It compares dependent-age groups with working-age groups, indicating potential support burdens rather than actual employment.'),
      l([t('Diffusion pathways','Relocation diffusion moves a trait with migrants; expansion diffusion spreads it while it remains in its source area. Hierarchies and social contact affect paths.','A trait may spread through more than one mechanism.'),t('Cultural landscapes','Buildings, land use, signs, and sacred spaces reflect cultural practices and power. Use visible evidence to support an interpretation.','A landscape feature alone does not prove every resident shares one identity.')],'Migrants establish restaurants using recipes from their home region. Identify the initial diffusion process.',['People physically relocate.','They carry cultural practices to a new location.'],'Relocation diffusion.','How does stimulus diffusion differ from exact copying?','An underlying idea spreads but is adapted to local conditions.'),
      l([t('State, nation, and sovereignty','A state governs a territory; a nation is a community with a shared identity. Their boundaries need not coincide.','A nation is not automatically a sovereign state.'),t('Boundaries and devolution','Boundaries can divide cultural groups or resources. Devolution transfers authority from a central government to subnational institutions.','Decentralization does not always mean independence.')],'A cultural group lives across three international borders. What distinction explains this?',['Identify shared identity as a national characteristic.','Identify legal territorial borders as state boundaries.'],'One nation can extend across multiple states.','How could a supranational organization affect sovereignty?','Members may coordinate or delegate selected decisions while retaining other national powers.'),
      l([t('Agricultural location and costs','Perishability, transport costs, land rent, and market access influence agricultural location. Models simplify these relationships.','Real transport networks and policy can alter model predictions.'),t('Agricultural intensification','Irrigation, fertilizer, machinery, and improved varieties can raise yields while changing labor needs and environmental pressures.','Higher yields do not eliminate distribution or access problems.')],'Why might a perishable crop be grown close to an urban market?',['Long trips increase spoilage risk and transport burdens.','Near-market land can be worth higher rent for that crop.'],'Location balances land cost against access and perishability.','Why can food insecurity persist despite sufficient national food production?','Income, distribution, conflict, and access can prevent households from obtaining available food.'),
      l([t('Urban networks','Cities serve different functions within interconnected networks of trade, services, and information. A large population is not the only source of influence.','Rank-size patterns and primacy are descriptions, not universal laws.'),t('Land use and displacement','Transport access, land values, zoning, and investment influence urban form. Redevelopment can improve amenities while displacing existing residents.','A neighborhood’s rising property value does not benefit every resident equally.')],'A new transit stop raises nearby demand for housing. Explain a possible benefit and cost.',['Improved access reduces travel burdens.','Higher rents can make housing less affordable for existing residents.'],'Accessibility gains can coexist with displacement pressure.','What distinguishes suburbanization from urbanization?','Suburbanization shifts people or activity toward metropolitan outskirts; urbanization increases the urban share of a population.'),
      l([t('Development measures','Income per person, health, and education capture different dimensions of development. Compare measures before making a broad judgment.','GDP per capita hides distribution within a country.'),t('Production networks','Firms locate stages of production using labor, infrastructure, markets, policy, and logistics. Outsourcing can redistribute jobs and environmental costs.','A product’s assembly location is not necessarily where most value is captured.')],'Two countries have similar income per person but different life expectancy. What follows?',['Income is only one development dimension.','Health outcomes can differ because of access, inequality, and public services.'],'Equal income averages do not imply equal living conditions.','Why can agglomeration attract firms?','Nearby suppliers, workers, knowledge, and infrastructure can lower costs or improve productivity.')
    ],
    appsych: [
      l([t('Action potentials and synaptic transmission','An action potential travels along an axon; neurotransmitters transmit signals across many synapses. Receptors and reuptake influence the signal’s effect.','A neuron’s firing strength is not a continuously variable action-potential amplitude.'),t('Sleep and research evidence','Sleep stages differ in brain activity and bodily patterns. Experimental manipulation supports different conclusions from a simple correlation between sleep and performance.','An association does not establish that one factor caused the other.')],'Students who sleep longer score higher on a test in an observational study. Can sleep be declared the cause?',['No random assignment to sleep conditions occurred.','Stress, health, or study routines might affect both variables.'],'The association alone does not establish causation.','What does an agonist generally do at a receptor?','It activates or enhances the receptor-related action of a neurotransmitter; effects depend on the receptor and system.'),
      l([t('Encoding and retrieval','Memory depends on how information is encoded, retained, and retrieved. Retrieval cues and practice can improve access without making memory infallible.','Feeling familiar with material is not the same as recalling it unaided.'),t('Heuristics and framing','Mental shortcuts can make judgments efficient but introduce systematic biases. Framing changes how equivalent information is presented.','A useful shortcut is not guaranteed to produce the correct answer.')],'A learner rereads notes easily but cannot answer with the notes closed. What should change?',['Recognize familiarity as a weak test of retrieval.','Practice answering without the notes, then use feedback to correct gaps.'],'Use retrieval practice rather than relying only on recognition.','What distinguishes proactive from retroactive interference?','Older learning disrupting new learning is proactive; newer learning disrupting older recall is retroactive.'),
      l([t('Classical conditioning sequence','A previously neutral stimulus can acquire the ability to elicit a response when paired with an unconditioned stimulus. Identify each stimulus and response in order.','A conditioned response is learned; an unconditioned response is not learned through that pairing.'),t('Consequences and behavior','Reinforcement increases a behavior; punishment decreases it. Positive means adding a stimulus, and negative means removing one.','Negative reinforcement is not punishment.')],'A car’s warning sound stops when the driver fastens a seat belt, increasing belt use. Classify it.',['The behavior increases, so the consequence is reinforcing.','An unpleasant sound is removed.'],'Negative reinforcement.','How can observational learning occur without direct reinforcement?','A learner can acquire a behavior by observing a model and its consequences.'),
      l([t('Attribution and situation','Explanations of behavior may emphasize dispositions or circumstances. The fundamental attribution error overemphasizes personal causes when judging others.','An observed action does not reveal a fixed personality trait by itself.'),t('Conformity and social influence','Normative influence involves acceptance or belonging; informational influence involves treating others as evidence about reality.','Public agreement need not indicate a private change in belief.')],'A student gives an answer they privately doubt to avoid standing out. Which influence best fits?',['The motive is social acceptance rather than new evidence.','Private doubt remains despite public agreement.'],'Normative social influence.','Why is one personality-test score not a complete description of a person?','Measurement reliability, context, and the range of traits assessed limit what a score can establish.'),
      l([t('Stress appraisal and coping','People appraise demands and available resources. Problem-focused coping targets a stressor; emotion-focused coping targets the emotional response.','Which approach helps depends partly on whether the situation is controllable.'),t('Evaluating treatment evidence','Controlled comparisons, reliable outcomes, and appropriate follow-up help evaluate an intervention. Improvement after treatment alone does not show what caused it.','This course content is not a basis for diagnosing yourself or another person.')],'A study compares change in a treatment group with change in a randomly assigned comparison group. Why compare changes?',['Both groups may change over time without the treatment.','The comparison helps separate the treatment effect from other influences.'],'A controlled comparison strengthens causal inference when design and measurement are sound.','What distinguishes reliability from validity in an assessment?','Reliability concerns consistency; validity concerns whether evidence supports the intended interpretation and use.')
    ],
    apprecalc: [
      l([t('Zeros, multiplicity, and sign', 'Factoring identifies zeros and their multiplicities. Near an isolated real zero, an odd multiplicity changes the sign while an even multiplicity preserves it; check the leading coefficient for end behavior.', 'Touching the axis is not evidence that the function has no zero.'), t('Holes and vertical asymptotes', 'Canceling a common factor simplifies a rational expression only on its original domain. A canceled denominator zero may create a hole; a remaining denominator zero creates a vertical asymptote when the numerator is nonzero there.', 'Keep excluded input values after canceling factors.')], 'Classify the discontinuities of f(x)=(x²−1)/(x²−x).', ['Factor the numerator as (x−1)(x+1) and denominator as x(x−1); exclude x=0 and x=1.', 'The simplified expression is (x+1)/x. At x=1 its limiting value is 2; at x=0 its denominator still vanishes.'], 'A hole at (1,2) and a vertical asymptote at x=0.', 'Does f(x)=(x−2)²(x+1) change sign at x=2? Explain.', 'No. The factor at 2 has even multiplicity; the graph touches the axis without changing sign there.'),
      l([t('Building an exponential model', 'For y=abˣ, the value a is the output at x=0 and b is the growth factor for one input unit. Given two positive outputs, divide them and account for the interval length before finding b.', 'A growth factor of 1.08 means an 8% increase, not a 108% increase.'), t('Logarithm laws and domains', 'For positive inputs, log(xy)=log x+log y and log(xʳ)=r log x. Use these laws to isolate an exponent, then verify that every original logarithm has a positive argument.', 'Logarithms do not distribute across addition: log(x+y) is not log x+log y.')], 'A culture has 200 cells initially and 800 after 6 hours. Model constant exponential growth.', ['In N(t)=200bᵗ, substitute t=6 to obtain b⁶=4.', 'Thus b=4^(1/6); write the model as 200·4^(t/6).'], 'N(t)=200·4^(t/6), with t in hours. The doubling time is 3 hours.', 'Solve log₂(x−1)=3 and check the domain.', 'x−1=8, so x=9. The required domain x>1 is satisfied.'),
      l([t('Unit-circle values and identities', 'On the unit circle, cos θ is the horizontal coordinate and sin θ is the vertical coordinate. The identity sin²θ+cos²θ=1 helps connect values, but quadrant information determines signs.', 'Taking a square root without checking the quadrant can give the wrong sign.'), t('Converting polar equations', 'The relationships x=r cos θ, y=r sin θ, and r²=x²+y² connect polar and Cartesian forms. Multiplying a polar equation by r can help convert it, but verify any origin behavior in the original description.', 'Angles are not Cartesian slopes, and negative r points opposite the named angle.')], 'Convert r=4 cos θ to a Cartesian equation and identify the curve.', ['Multiply by r: r²=4r cos θ, giving x²+y²=4x.', 'Complete the square: (x−2)²+y²=4.'], 'A circle centered at (2,0) with radius 2; the origin is included.', 'If sin θ=3/5 and θ lies in quadrant II, what is cos θ?', 'cos θ=−4/5: the identity gives magnitude 4/5, and cosine is negative in quadrant II.')
    ],
    apphyscmech: [
      l([t('Displacement versus total distance', 'Integrating signed velocity gives displacement. Total distance is the integral of speed, so split the interval wherever velocity changes sign before adding positive path lengths.', 'A zero net displacement does not imply that the particle stayed still.'), t('Vector motion and components', 'Differentiate or integrate each Cartesian component separately. Speed is the magnitude of the velocity vector, and acceleration can be nonzero even when speed is constant because direction changes.', 'The derivative of speed alone does not capture acceleration perpendicular to motion.')], 'A particle has v(t)=2t−4 m/s from t=0 to t=4 s. Find displacement and distance.', ['Velocity changes sign at t=2. The displacement integral is [t²−4t] from 0 to 4, which is 0.', 'From 0 to 2 the displacement is −4 m; from 2 to 4 it is +4 m. Add their magnitudes.'], 'Displacement is 0 m; total distance is 8 m.', 'At constant speed in a circle, is acceleration zero? Explain.', 'No. The velocity direction changes; the inward acceleration has magnitude v²/r.'),
      l([t('Free-body diagrams and friction', 'Choose a system and draw only forces exerted on it. Static friction adjusts up to μsN, while sliding friction has magnitude μkN in the ideal model; resolve forces along useful axes before applying Newton’s law.', 'Static friction is not automatically equal to μsN.'), t('Linear drag and terminal speed', 'With downward positive, a falling object under linear drag satisfies m dv/dt=mg−bv. Terminal speed occurs when acceleration vanishes, giving vterminal=mg/b, and is approached asymptotically in this model.', 'Terminal speed means balanced forces, not an absence of gravity or drag.')], 'A 2 kg block rests on a horizontal table with μs=0.4. A horizontal 5 N force is applied. Use g=10 m/s².', ['The normal force is 20 N, so the maximum static friction is 8 N.', 'Since 5 N is below this maximum, static friction balances the applied force.'], 'The block stays at rest; static friction is 5 N opposite the applied force.', 'An object falls at terminal speed under gravity and drag. What is its net force?', 'Zero: drag balances weight, so acceleration is zero even though the object is moving.'),
      l([t('Energy systems and nonconservative work', 'Specify which interactions are represented by potential energy. For a system with kinetic and potential energy, external work and dissipative transfers can change mechanical energy; friction often converts mechanical energy into thermal energy.', 'Do not count the same gravitational interaction as both work and a potential-energy change.'), t('Instantaneous power', 'Power is the time rate of energy transfer. For a force acting on a particle, P=F·v; only the component parallel to velocity contributes, and the sign indicates whether that force adds or removes kinetic energy.', 'A large perpendicular force can do zero work and deliver zero instantaneous power.')], 'A 2 kg cart moves from x=0 to x=3 m under F(x)=4x N, starting at 1 m/s on a frictionless track. Find its final speed.', ['Work is ∫₀³4x dx=18 J. Initial kinetic energy is (1/2)(2)(1²)=1 J.', 'The work-energy theorem gives final kinetic energy 19 J, so (1/2)(2)v²=19.'], 'v=√19 m/s, approximately 4.36 m/s.', 'What is the power of a 10 N force perpendicular to a velocity of magnitude 3 m/s?', '0 W, because F·v=Fv cos 90°=0.'),
      l([t('Collisions and system boundaries', 'Momentum is conserved during an interaction when net external impulse is negligible. Kinetic energy is conserved only in an elastic collision; objects sticking together undergo a perfectly inelastic collision.', 'Internal collision forces do not change total system momentum, but they can change kinetic energy.'), t('Explosions and recoil', 'An initially stationary isolated system has zero total momentum before and after an explosion or recoil event. Individual parts may gain kinetic energy supplied by stored internal energy while their vector momenta cancel.', 'Momentum conservation does not require conservation of kinetic energy.')], 'A 2 kg cart moving at 3 m/s sticks to a stationary 1 kg cart. Find their speed and kinetic-energy change.', ['Initial momentum is 6 kg·m/s. Dividing by combined mass 3 kg gives v=2 m/s.', 'Initial kinetic energy is 9 J; final kinetic energy is (1/2)(3)(2²)=6 J.'], 'The combined carts move at 2 m/s; kinetic energy decreases by 3 J.', 'Two stationary fragments fly apart after an internal explosion. Must their speeds be equal?', 'Only if their masses are equal. Their momenta are equal in magnitude and opposite in direction, so the lighter fragment moves faster.'),
      l([t('Torque vectors and lever arms', 'Torque about a chosen origin is r×F. Its magnitude is rF sin θ, equivalently force times perpendicular lever arm; a force through the axis exerts zero torque about that axis.', 'The distance along a rod is not always the perpendicular lever arm.'), t('Moment of inertia from integration', 'Moment of inertia is ∫r² dm, where r is perpendicular distance to the rotation axis. Express dm using the mass distribution, and choose integration limits that match the object and axis.', 'Moment of inertia depends on the axis as well as total mass and shape.')], 'Derive the moment of inertia of a uniform thin rod of length L and mass M about an axis perpendicular to one end.', ['Uniform linear density is M/L, so dm=(M/L) dx at distance x from the end.', 'Integrate I=(M/L)∫₀ᴸx² dx=(M/L)(L³/3).'], 'I=ML²/3 about the stated end axis.', 'A 5 N force acts along a rod directly toward its pivot. What torque does it produce about that pivot?', 'Zero. Its line of action passes through the pivot, so its perpendicular lever arm is zero.'),
      l([t('Angular momentum conservation', 'Angular momentum about a chosen origin stays constant when net external torque about that origin is zero. For a body rotating around a fixed principal axis, L=Iω, so decreasing I increases ω when L is conserved.', 'Conserved angular momentum does not by itself imply conserved rotational kinetic energy.'), t('Rolling constraints and friction', 'For rolling without slipping on a stationary surface, vcm=ωR. Static friction can provide torque without dissipating energy in the ideal rigid-body model; distinguish this condition from slipping, where the constraint fails.', 'The translational and rotational kinetic energies must both be included for rolling.')], 'A solid cylinder starts from rest and rolls without slipping down a height h. Use I=(1/2)MR² to find its bottom speed.', ['Conservation of energy gives Mgh=(1/2)Mv²+(1/2)Iω².', 'Substitute I=(1/2)MR² and ω=v/R to obtain Mgh=(3/4)Mv².'], 'v=√(4gh/3), assuming ideal rolling and no dissipative losses.', 'A rotating skater halves her moment of inertia with negligible external torque. How does angular speed change?', 'It doubles, because Iω remains constant. The extra kinetic energy comes from internal work.'),
      l([t('Oscillation energy and phase', 'For an ideal mass-spring oscillator, total energy is (1/2)kA². Kinetic energy is greatest at equilibrium and spring potential energy is greatest at the turning points; displacement and velocity differ in phase by a quarter cycle.', 'At a turning point velocity is zero, but acceleration has its largest magnitude.'), t('Equilibrium shifts and period', 'For a vertical ideal spring, gravity shifts the equilibrium extension to mg/k. Measuring displacement from that equilibrium gives m d²y/dt²=−ky, so the period remains 2π√(m/k).', 'Do not add gravity again after writing the restoring-force equation relative to equilibrium.')], 'A 0.50 kg mass on an ideal spring with k=8 N/m oscillates with amplitude 0.10 m. Find angular frequency and maximum speed.', ['ω=√(k/m)=√16=4 rad/s.', 'Maximum speed occurs at equilibrium and is ωA=4(0.10).'], 'ω=4 rad/s and vmax=0.40 m/s.', 'If the mass on an ideal spring is quadrupled while k is fixed, what happens to the period?', 'It doubles, because T=2π√(m/k).')
    ],
    apmacro: [
      l([t('Production possibilities and growth', 'A production possibilities frontier shows efficient output combinations with available resources and technology. An interior point indicates underused resources; growth shifts the frontier outward.', 'Moving toward the frontier improves resource use but does not itself shift the frontier.'), t('Terms of trade', 'Mutually beneficial exchange can occur when the trade price lies between the producers’ opportunity costs. Compare costs in the same units before choosing specialization.', 'Absolute productivity does not determine comparative advantage.')], 'A can make 12 meals or 6 repairs per day; B can make 8 meals or 8 repairs. Who should specialize in repairs?', ['For A, one repair costs 12/6 = 2 meals.', 'For B, one repair costs 8/8 = 1 meal; B has the lower opportunity cost.'], 'B specializes in repairs. A trade price between 1 and 2 meals per repair can benefit both.', 'Does unemployment place an economy on or inside its production possibilities frontier?', 'Inside: some available productive resources are not being used.'),
      l([t('Price indexes and inflation', 'A price index compares the cost of a basket with its base-year cost. Inflation is the percentage change in the index between periods, not the index level itself.', 'An index of 120 means prices are 20% above the base, not necessarily 20% above last year.'), t('Labor force and unemployment types', 'The labor force includes employed people and people actively seeking work. Frictional and structural unemployment can remain at full employment; cyclical unemployment rises in recessions.', 'A discouraged worker who stops searching leaves both the unemployed count and the labor force.')], 'The consumer price index rises from 125 to 130. What is the inflation rate?', ['Find the change: 130 − 125 = 5.', 'Divide by the earlier index and multiply by 100: 5/125 × 100.'], '4% inflation.', 'If employed workers number 90 and active job seekers number 10, what is the unemployment rate?', '10/(90+10) × 100 = 10%; the denominator is the labor force.'),
      l([t('Spending and tax multipliers', 'In a simple closed economy without crowding out, the spending multiplier is 1/(1−MPC). The tax multiplier is −MPC/(1−MPC), because part of a tax change is initially saved.', 'A transfer payment or tax cut is not directly counted as government purchases in GDP.'), t('Recessionary and inflationary gaps', 'Compare equilibrium real output with potential output. Expansionary fiscal policy raises aggregate demand; contractionary policy lowers it. Supply shocks can change both output and prices in opposite directions.', 'A negative supply shock cannot be described as an aggregate-demand decrease.')], 'With MPC = 0.75, what government-purchases increase closes a $40 billion recessionary gap in the simple multiplier model?', ['The spending multiplier is 1/(1−0.75) = 4.', 'Required spending is the output gap divided by the multiplier: 40/4.'], '$10 billion, assuming constant prices and no offsetting effects.', 'Why is a $10 billion tax cut less expansionary than a $10 billion purchases increase when MPC < 1?', 'Households initially spend only the MPC fraction of the tax cut; purchases enter aggregate demand directly.'),
      l([t('Real interest and bond prices', 'The approximate real interest rate equals the nominal rate minus inflation. Fixed-payment bond prices and market interest rates move in opposite directions because investors compare alternative yields.', 'Expected inflation matters for the expected real rate; actual inflation determines the realized rate.'), t('Monetary policy operating systems', 'In a limited-reserves model, central-bank security purchases add reserves and can lower short-term rates. With ample reserves, administered rates such as interest on reserve balances are central policy tools.', 'Do not assume a reserve multiplier describes actual lending without assumptions about reserves and cash holding.')], 'A one-year loan charges 7% nominal interest; expected inflation is 3%, but actual inflation is 5%. Compare expected and realized real rates.', ['Subtract expected inflation for the expected real return: 7−3.', 'Subtract actual inflation for the realized real return: 7−5.'], 'Approximately 4% expected and 2% realized; unexpected inflation reduces the lender’s real return.', 'What happens to the market price of an existing fixed-payment bond when market interest rates rise?', 'It falls, so its yield becomes more competitive with newly issued bonds.'),
      l([t('Phillips curve expectations', 'The short-run Phillips curve relates unemployment and inflation for given expectations and supply conditions. Changed expected inflation shifts it; the long-run curve is vertical at the natural unemployment rate.', 'A permanent inflation–unemployment tradeoff is not implied by the short-run curve.'), t('Productivity and long-run growth', 'More physical capital, human capital, and better technology can increase potential output. Real GDP per capita distinguishes average output growth from growth caused only by population increases.', 'A temporary increase in aggregate demand does not alone raise productive capacity.')], 'Suppose actual unemployment is below its natural rate and inflation expectations subsequently rise. How does the short-run Phillips curve change?', ['Workers and firms adjust nominal wages and prices to higher expected inflation.', 'At each unemployment rate, inflation is now higher than before.'], 'The short-run Phillips curve shifts upward; the long-run natural-rate benchmark is unchanged if structural conditions are unchanged.', 'Does a higher nominal GDP necessarily mean higher real output per person?', 'No. Higher prices or a larger population can raise nominal GDP without improving real output per person.'),
      l([t('Currency appreciation and net exports', 'When a currency appreciates, domestic goods become more expensive to foreign buyers and foreign goods become cheaper to domestic buyers, tending to lower net exports, other things equal.', 'Always identify which currency is quoted; reciprocal exchange-rate quotations move oppositely.'), t('Current and financial accounts', 'The current account records trade in goods and services and net income and transfers. The financial account tracks cross-border asset transactions; imports and purchases of foreign assets are different entries.', 'Buying a foreign company’s bond is a financial transaction, not an import of a service.')], 'The dollar rises from €0.80 to €1.00 per dollar. How does the euro price of a fixed $100 U.S. product change?', ['Initially $100 × €0.80/$ = €80.', 'After appreciation $100 × €1.00/$ = €100.'], 'It rises from €80 to €100, tending to reduce foreign demand for the U.S. product.', 'If higher domestic real interest rates attract foreign investment, what tends to happen to demand for the domestic currency?', 'It increases as investors exchange currencies to buy domestic assets, tending to appreciate the domestic currency.')
    ],
    apmicro: [
      l([t('Economic versus accounting profit', 'Accounting profit subtracts explicit costs from revenue. Economic profit also subtracts implicit opportunity costs, including the owner’s forgone earnings from the next best alternative.', 'Zero economic profit can coexist with positive accounting profit and keeps resources in their current use.'), t('Production possibilities tradeoffs', 'The slope of a production possibilities frontier measures opportunity cost. A bowed-out frontier reflects increasing opportunity cost as resources less suited to a task move into that task.', 'An efficient output combination need not be the combination society prefers.')], 'A business earns $100,000 revenue, pays $60,000 explicit costs, and its owner forgoes a $30,000 salary. Find both profits.', ['Accounting profit is 100,000 − 60,000.', 'Economic profit additionally subtracts the forgone salary: 40,000 − 30,000.'], '$40,000 accounting profit and $10,000 economic profit.', 'If the marginal benefit of another unit is $8 and its marginal cost is $11, should an optimizing buyer purchase it?', 'No. The extra cost exceeds the extra benefit by $3.'),
      l([t('Binding price controls', 'A price ceiling below equilibrium creates a shortage; a price floor above equilibrium creates a surplus. Nonbinding controls do not change the competitive equilibrium.', 'A ceiling above equilibrium is not a shortage-producing constraint.'), t('Tax incidence and welfare', 'A per-unit tax creates a wedge between the buyer’s price and seller’s receipt. The less elastic side bears more of the burden; lost mutually beneficial trades create deadweight loss.', 'The legal requirement to send tax payments does not determine who bears the economic burden.')], 'At a binding $6 price ceiling, quantity demanded is 120 and quantity supplied is 80. What shortage results?', ['Compare quantity demanded with quantity supplied at the controlled price.', 'Subtract 80 from 120; actual transactions are constrained by supply.'], 'A shortage of 40 units; at most 80 units trade under these assumptions.', 'If demand is very inelastic and supply is elastic, who usually bears more of a per-unit tax?', 'Buyers, because their quantity demanded responds less to price changes.'),
      l([t('Profit, shutdown, and exit', 'Profit equals (price−average total cost) times quantity. A competitive firm may operate at a short-run loss if price covers average variable cost; long-run exit considers all costs.', 'A loss does not automatically imply immediate shutdown because fixed costs remain in the short run.'), t('Long-run entry and efficiency', 'Positive economic profit attracts entry into a competitive market, expanding supply and reducing price. With free entry and identical firms, long-run equilibrium yields zero economic profit at minimum average total cost.', 'Zero economic profit means opportunity costs are covered, not that owners receive nothing.')], 'A competitive firm produces 100 units at P=$8, ATC=$10, and AVC=$6. Should it shut down immediately?', ['Profit is (8−10) × 100 = −$200.', 'Price exceeds AVC, so operating covers variable costs and part of fixed costs.'], 'It incurs a $200 loss but should continue in the short run at its profit-maximizing output; shutdown would lose all fixed costs.', 'At the efficient scale of a competitive firm in long-run equilibrium, how do price, marginal cost, and average total cost compare?', 'P = MC = minimum ATC, under the standard free-entry model.'),
      l([t('Price discrimination conditions', 'Price discrimination requires market power, a way to distinguish willingness to pay, and limits on resale. Perfect price discrimination can capture consumer surplus and expand output toward the efficient quantity.', 'Charging different prices because production costs differ is not necessarily price discrimination.'), t('Monopolistic competition and entry', 'Differentiated products give each firm a downward-sloping demand curve. Free entry erodes economic profit; long-run output can remain below the quantity that minimizes average total cost.', 'Zero economic profit does not make monopolistic competition productively or allocatively efficient.')], 'A monopolist has MR=MC at 40 units. Demand gives P=$12 there and ATC=$9. Find profit.', ['Choose quantity using MR=MC, then read price from demand rather than marginal revenue.', 'Compute (12−9) × 40.'], '$120 economic profit.', 'Can a firm freely set both the price and quantity buyers purchase on its demand curve?', 'No. Choosing a price determines the quantity buyers demand; the firm is constrained by that relationship.'),
      l([t('Competitive labor-market wages', 'A wage-taking firm faces a horizontal labor supply at the market wage. It hires workers while additional revenue from labor covers the additional wage expense.', 'A worker’s physical output must be valued in revenue terms before comparing it with a dollar wage.'), t('Monopsony and marginal factor cost', 'A single major buyer of labor faces upward-sloping labor supply. When it must raise pay for all workers to hire another, marginal factor cost exceeds the wage; employment is chosen at MRP=MFC.', 'For a monopsonist, read the wage from labor supply at the chosen employment, not from the MFC curve.')], 'A price-taking firm sells output at $5 per unit. A worker adds 6 units and costs $25. Is hiring that worker worthwhile?', ['Marginal revenue product is 6 × $5 = $30.', 'Compare $30 additional revenue with the $25 marginal labor cost.'], 'Yes; this worker adds $5 to profit, assuming no other marginal costs.', 'What happens to labor demand when a complementary technology raises workers’ marginal product, other things equal?', 'Labor demand shifts right because marginal revenue product rises at each employment level.'),
      l([t('Social versus private marginal cost', 'With a negative production externality, marginal social cost exceeds marginal private cost. Competitive output is too high when producers ignore external harm; the efficient quantity equates social benefit and social cost.', 'A corrective tax is linked to marginal external harm at the efficient output, not total harm.'), t('Common resources and property rights', 'Common resources are rival but difficult to exclude people from using, so individual use can deplete what remains for others. Clearly defined rights or collective rules can reduce overuse.', 'Common resources are rival; public goods are nonrival. Both can be nonexcludable.')], 'A factory’s marginal private cost at the efficient quantity is $12 and marginal social cost is $17. What per-unit corrective tax aligns incentives?', ['Find marginal external cost: 17−12 = $5.', 'A $5 tax makes the producer face the $17 social marginal cost at that quantity.'], '$5 per unit, assuming the external-cost estimate is accurate.', 'Why can an open-access fishery be overharvested even when each fisher acts rationally?', 'Each fisher receives the private catch benefit while sharing the depletion cost with others, so private incentives can exceed the socially efficient harvest.')
    ],
    aplang: [
      l([t('Exigence versus purpose', 'Exigence is the situation that prompts a response; purpose is what the writer hopes the response will accomplish. Tie each to specific textual details.', 'A topic alone does not identify why this audience is addressed now.'), t('Audience assumptions', 'Writers select examples and appeals based on what their audience values or already believes. Explain how a choice meets that particular audience.', 'Calling something emotional does not explain its persuasive function.')], 'A principal addresses parents after bus delays, beginning with their lost work time. Why open this way?', ['Identify the immediate problem: repeated delays have prompted the message.', 'Connect the opening detail to parents’ concerns about reliability and work.'], 'Acknowledging parents’ costs establishes shared concern before the principal proposes a scheduling change.', 'How does exigence differ from a writer’s purpose?', 'Exigence prompts the response; purpose is its intended effect on the audience.'),
      l([t('Evidence specificity', 'Concrete examples need enough detail to demonstrate the claim. Explain the mechanism connecting an example to a broader principle instead of merely naming a famous event.', 'A list of impressive names is not developed evidence.'), t('Counterargument and response', 'Represent a reasonable objection accurately, then concede its valid limits or explain why your position still holds. This can clarify the scope of your argument.', 'Inventing an easily defeated objection weakens your reasoning.')], 'Improve the reasoning for the claim that libraries should offer evening hours, using a survey of working adults.', ['Specify what the survey actually measured, such as preferred opening times.', 'Explain how evening access addresses the conflict between work schedules and library hours.'], 'The survey supports extending hours for the surveyed population; it does not by itself prove every branch needs the same schedule.', 'Why does a relevant statistic still need commentary?', 'The writer must explain how the measured fact supports the particular claim and acknowledge its limits.'),
      l([t('Paragraph relationships', 'A paragraph can introduce a problem, explain a cause, concede an objection, or establish a consequence. Name its role in the argument before evaluating its placement.', 'A transition word cannot repair a missing logical relationship.'), t('Syntax and emphasis', 'Sentence length, parallel structure, and placement can emphasize an idea. Analyze the effect using the actual wording and rhetorical context.', 'Short sentences do not always create urgency; their effect depends on context.')], 'An essay explains a policy’s benefits, concedes its cost, then proposes a funding plan. What does this order accomplish?', ['The benefits establish why the policy is worth considering.', 'The concession anticipates resistance, and the funding plan responds to that resistance.'], 'The sequence builds a case while treating a practical objection as part of the argument.', 'What should follow identifying parallel structure in a passage?', 'Explain which ideas the repetition links or emphasizes and how that effect advances the writer’s purpose.'),
      l([t('Source credibility and scope', 'Evaluate a source’s expertise, methods, date, and purpose. A credible source can still have a narrow scope that limits the claim it supports.', 'An institutional logo does not make every conclusion equally well supported.'), t('Synthesis tensions', 'Sources may agree on a problem while disagreeing about its cause or remedy. Organize paragraphs around your claims and use those differences to develop reasoning.', 'One paragraph per source often produces a report instead of an argument.')], 'Source A shows transit lowers emissions; Source B shows low ridership on rural routes. Synthesize them in a policy claim.', ['Identify the compatible findings: environmental benefits depend partly on use.', 'Limit the proposed policy to places where the evidence supports likely demand.'], 'Prioritize transit expansion where expected ridership can deliver environmental benefits, while examining alternatives for low-demand routes.', 'Must agreeing with a source mean accepting its entire argument?', 'No. A writer can use a supported finding while qualifying another claim or disputing its proposed solution.')
    ],
    aplit: [
      l([t('Indirect characterization', 'A character’s actions, omissions, dialogue, and reactions reveal values. Examine tensions between what a character says and does before making an interpretation.', 'A single adjective rarely captures a complex character.'), t('Setting as pressure', 'Social rules and physical surroundings can constrain choices and heighten conflict. Connect a setting detail to a character’s response rather than treating scenery as decoration.', 'Weather does not have one automatic symbolic meaning.')], 'A character calls a visitor unwelcome but sets out a second cup. What interpretation does this detail support?', ['Contrast the spoken rejection with the hospitable action.', 'Infer a tension between defensive language and a desire for companionship.'], 'The contradiction suggests guarded longing, provided the surrounding passage supports that reading.', 'How can a narrator’s report differ from the author’s position?', 'The narrator is a constructed perspective; irony or conflicting details may invite readers to question that perspective.'),
      l([t('Poetic turns', 'A shift in diction, imagery, address, or syntax can change the speaker’s attitude. Locate the turn and explain the relationship between the poem’s earlier and later movement.', 'A new stanza does not automatically signal a change in attitude.'), t('Enjambment and end stopping', 'Enjambment carries syntax across a line break; an end-stopped line closes a phrase or sentence. Consider how the break affects pace, expectation, or emphasis.', 'Do not assume every line break marks a grammatical pause.')], 'An original poem begins “I counted every loss” and ends “I count the hands still here.” What shift might you analyze?', ['Notice the repeated act of counting and the change in its object.', 'Connect loss to absence and hands to surviving human connection.'], 'The poem can move from accounting for absence toward recognizing companionship without erasing grief.', 'Why is the speaker not automatically the poet?', 'A poem constructs a voice and situation that may differ from the writer’s own identity or experience.'),
      l([t('Foils and contrasting choices', 'Characters facing similar pressures may choose differently. Their contrast can reveal values and complicate a work’s treatment of responsibility or desire.', 'A foil need not be an enemy or a purely opposite personality.'), t('Dramatic irony', 'When an audience knows something a character does not, the gap can create tension and alter the meaning of otherwise ordinary dialogue or action.', 'Irony is not simply any surprising event.')], 'In an invented play, the audience sees a letter hidden before a character accuses a friend of never replying. What is the effect?', ['Separate the audience’s knowledge from the accusing character’s knowledge.', 'Explain how that gap changes the accusation’s apparent justification.'], 'Dramatic irony makes the accusation tragically mistaken and builds tension around whether the concealed letter will emerge.', 'How can a recurring object develop meaning across a novel?', 'Its different contexts can change or complicate its associations; trace those changes rather than assigning a fixed symbolic definition.'),
      l([t('Complexity through tension', 'Develop an interpretation that accounts for conflicting motives or consequences. Complexity comes from the text’s relationships, not from adding vague claims about human nature.', 'A complicated sentence is not the same as a complex interpretation.'), t('Selecting pivotal moments', 'Choose a few consequential details from the work and explain how they develop the thesis. Accurate paraphrase can support analysis without memorized quotations.', 'Retelling the entire plot leaves little room to explain meaning.')], 'Revise “The character is ambitious” into an interpretive claim about a character who wins power but loses trust.', ['Identify the tension between external success and damaged relationships.', 'Connect that tension to the work’s treatment of ambition.'], 'The character’s ascent makes ambition self-defeating: gaining authority destroys the trust needed to exercise it securely.', 'What makes a plot detail evidence in a literary argument?', 'Its explained connection to the thesis, including how the detail supports an interpretation of the work’s meaning.')
    ],
    apspan: [
      l([t('Practices and perspectives', 'Describe a specific community practice, then explain the values it may express using research evidence. “En esta comunidad…” is more precise than a claim about all Spanish speakers.', 'Do not generalize one family’s experience to an entire country.'), t('Requests and clarification', 'Use polite questions suited to the relationship: “¿Podría explicar…?” or “¿A qué se refiere con…?” Clarification keeps an exchange moving when meaning is uncertain.', 'Pretending to understand can lead to an unrelated response.')], 'You interview a community organizer and do not understand who can attend a neighborhood event. Ask a useful question.', ['Use a respectful register appropriate to an unfamiliar adult.', 'Name the missing information instead of asking the speaker to repeat everything.'], '“¿Podría aclarar si el evento está abierto a todos los vecinos o solo a los socios?”', 'Why is “En la comunidad que investigué…” useful in a cultural comparison?', 'It identifies the scope of the evidence and avoids presenting a local practice as universal.'),
      l([t('Narrating identity over time', 'Use the imperfect for background or habitual conditions and the preterite for bounded events: “Hablaba español en casa; el año pasado participé en un intercambio.”', 'Choosing tense depends on intended meaning, not merely a time-word list.'), t('Evidence and inference language', 'Distinguish stated facts from interpretations: “La autora afirma…” reports a claim; “Esto sugiere…” marks an inference that still needs textual support.', 'Do not present your inference as a quotation from the source.')], 'A speaker says she uses one language at home and another at school. State a supported inference in Spanish.', ['Identify the explicit contrast between social settings.', 'Offer a cautious interpretation without assuming the speaker feels ashamed or conflicted.'], '“Esto sugiere que adapta su uso del idioma al contexto social; no demuestra que rechace ninguna de sus identidades.”', 'How does “afirma” differ from “sugiere” when discussing a source?', '“Afirma” attributes an explicit statement; “sugiere” signals an interpretation supported by details.'),
      l([t('Describing visual evidence', 'Name observable features before interpreting them: “En primer plano se ve…” and “El contraste entre… destaca…”. Connect color, composition, or materials to the claim.', 'Personal preference alone does not explain a work’s cultural significance.'), t('Supporting aesthetic judgments', 'Use a specific criterion such as craftsmanship, innovation, or public function. A comparison can recognize different purposes without ranking entire cultures.', 'Avoid treating one cultural standard of beauty as universal.')], 'Compare two invented murals: one depicts local workers and another uses abstract shapes. Make an evidence-based comparison.', ['Describe each mural’s visible subjects instead of guessing the artists’ intentions.', 'Explain a meaningful difference in how viewers are invited to interpret the work.'], '“Mientras que el primer mural representa oficios reconocibles, el segundo invita a interpretar formas abstractas; ambos pueden crear una identidad visual para el barrio.”', 'What should support a claim that an artwork celebrates a community?', 'Specific features and contextual evidence, such as depicted people, commissioned purpose, or documented community responses.'),
      l([t('Cause and consequence in Spanish', 'Connect a proposed mechanism to an outcome with “debido a”, “por lo tanto”, or “como consecuencia”. State what the evidence actually establishes before claiming causation.', 'An increase occurring after a new technology does not by itself prove causation.'), t('Recommendations and uncertainty', 'Use structures such as “Es importante que se protejan los datos” for recommendations and “Es posible que…” for uncertainty. Match the mood to the intended meaning.', 'Do not use certainty language when the source only predicts a possibility.')], 'A report describes an app that collects student location data. Propose a balanced recommendation in Spanish.', ['Acknowledge the app’s stated educational benefit without inventing proof of success.', 'Identify a concrete privacy condition for its use.'], '“Aunque la aplicación puede facilitar la coordinación, es importante que la escuela limite la recopilación de datos y explique quién puede consultarlos.”', 'Why should “podría reducir” sometimes replace “elimina” in a technology argument?', 'It expresses a possible reduction rather than an unsupported guarantee that a problem disappears.'),
      l([t('Research attribution in speech', 'Introduce evidence naturally: “Según la encuesta del ayuntamiento…”. Include enough information for listeners to understand the source and connect the finding to your question.', 'A number without its population or source can be misleading.'), t('Repairing a spoken answer', 'When vocabulary fails, paraphrase with a known phrase: “Es un lugar donde…” or “Me refiero a…”. Answer the question first, then add a relevant supporting detail.', 'Long memorized material can drift away from the question asked.')], 'You are asked why your project focused on public transport rather than shopping habits. Give a direct Spanish response.', ['State the research reason immediately.', 'Support it with the project’s scope rather than an unrelated prepared speech.'], '“Elegí el transporte porque mi investigación trata del acceso a la escuela. Comparé los horarios de los autobuses con las horas de entrada.”', 'What should you do if an audience question is unclear?', 'Ask a focused clarification in Spanish, then answer the clarified question with relevant project evidence.'),
      l([t('Evaluating proposed solutions', 'Identify who benefits, who pays, and what conditions a solution requires. Use “por una parte” and “por otra parte” to organize genuine tradeoffs, then state your judgment.', 'Listing both sides without deciding or qualifying a position does not build an argument.'), t('Quantities and audio evidence', 'Record units, time periods, and comparisons when listening to numerical evidence. Distinguish “aumentó a” from “aumentó en” to avoid confusing a final level with a change.', 'A percentage and a percentage-point change are not interchangeable.')], 'A recording says recycling participation rose from 20% to 30%. Explain the change accurately in Spanish.', ['Subtract the two rates to find the percentage-point change.', 'Divide the increase by the initial rate only if reporting relative percentage growth.'], '“La participación aumentó diez puntos porcentuales, del veinte al treinta por ciento”; el aumento relativo fue del cincuenta por ciento.', 'Why should an environmental proposal identify different affected groups?', 'Costs, benefits, and practical constraints may differ across groups; that evidence helps evaluate feasibility and fairness.')
    ],
    apcompgov: [
      l([t('State, regime, and government', 'The state comprises enduring governing institutions; a regime is the rules for acquiring and exercising power; a government is the current leadership. Leadership can change without regime change.', 'An election replacing a cabinet does not necessarily create a new regime.'), t('Empirical and normative claims', 'Empirical claims describe or explain observations; normative claims judge what should be. Support an empirical comparison with measurable indicators and explicit definitions.', 'A personal preference is not evidence that an institution performs better.')], 'A prime minister is replaced while electoral and constitutional rules remain intact. What changed?', ['Identify the leadership change as a change in the government.', 'Check whether the rules of political competition or state institutions were replaced.'], 'The government changed; the facts given do not establish a regime change or a new state.', 'Can a state have strong capacity but limited democratic accountability?', 'Yes. Capacity concerns implementation ability; democracy concerns participation, competition, and constraints on rulers.'),
      l([t('Federal and unitary authority', 'Federal systems constitutionally divide authority between national and regional governments. Unitary systems concentrate ultimate authority nationally, even when substantial powers are devolved.', 'Devolution does not automatically turn a unitary state into a federation.'), t('Formal rules and actual power', 'A constitution may assign oversight powers that officials cannot effectively exercise. Compare legal design with enforcement, party discipline, and informal political pressures.', 'The existence of a legislature alone does not demonstrate effective executive accountability.')], 'Compare regional authority in the United Kingdom and Nigeria at the level of constitutional design.', ['Distinguish devolved institutions within the United Kingdom’s unitary framework from constitutionally divided federal authority.', 'Identify Nigeria as a federal system with national and state governments.'], 'Both have regional institutions, but their constitutional sources of authority differ: devolution in the United Kingdom and federal division in Nigeria.', 'Why might two legislatures with similar formal powers constrain executives differently?', 'Party control, institutional resources, enforcement, and political pressures affect whether formal oversight powers are actually used.'),
      l([t('Political socialization', 'Families, schools, media, religion, and political experience shape beliefs about authority and participation. Explain a plausible mechanism instead of assuming one identity causes a fixed opinion.', 'Members of the same social group do not necessarily share every political belief.'), t('Participation under constraints', 'Voting, protest, petitions, and civic organizing have different costs under different regimes. Participation rates alone do not reveal whether participation is free or meaningful.', 'High turnout is not sufficient evidence of democratic competition.')], 'Two countries report high turnout, but one restricts opposition candidates. Can turnout alone establish equal democratic participation?', ['Compare the choices available to voters, not just the number voting.', 'Examine coercion, competition, and access to political information.'], 'No. Similar turnout can occur under very different conditions of freedom and meaningful competition.', 'How can social media affect participation in more than one direction?', 'It may lower organizing costs while also enabling censorship, surveillance, or misinformation that constrains participation.'),
      l([t('District magnitude and representation', 'District magnitude is the number of seats elected in a district. Together with allocation rules and thresholds, it affects how votes translate into seats.', 'A party’s national vote share need not equal its seat share.'), t('Electoral competition and dominance', 'Distinguish a party repeatedly winning competitive elections from institutions that exclude rivals. Examine ballot access, media access, and electoral administration.', 'The number of legally registered parties alone does not measure meaningful competition.')], 'In a single-member plurality district, candidates receive 40%, 35%, and 25%. Who wins, and what does the result show?', ['Apply plurality: the largest vote total wins the seat.', 'Distinguish a plurality from an absolute majority of votes.'], 'The 40% candidate wins despite lacking majority support; the other votes do not produce representation in that district.', 'Why can geographically concentrated support matter in single-member districts?', 'Concentration can help a party win individual districts even when its national vote share is relatively small.'),
      l([t('Economic liberalization versus political liberalization', 'Economic liberalization expands market activity; political liberalization expands freedoms or competition. One can occur without the other, so specify which change the evidence measures.', 'Privatization alone does not prove democratization.'), t('Resource dependence and accountability', 'Heavy reliance on resource revenue may reduce dependence on broad taxation and expose budgets to price swings. Its political effects depend on institutions and revenue management.', 'Natural resources do not determine one inevitable political outcome.')], 'A government permits private firms but continues restricting opposition parties. How should the reform be described?', ['Identify increased private economic activity as an economic change.', 'Check for independent evidence of expanded political rights or competition.'], 'It is economic liberalization; the facts do not show political liberalization or democratization.', 'Why might falling oil prices strain a resource-dependent government?', 'Lower export and fiscal revenue can reduce spending capacity, creating policy tradeoffs and potential pressure on legitimacy.')
    ],
  };
  // BC groups the shared AB foundation into two review units; retain its breadth.
  lessons.apcalcbc[0].topics.push(...lessons.apcalcab.slice(0,5).flatMap(unit => unit.topics));
  lessons.apcalcbc[1].topics.push(...lessons.apcalcab.slice(5,8).flatMap(unit => unit.topics));
  root.ScholarkAPLessons = lessons;
})(window);
